class RunnerError(Exception):
    """A bounded fail-closed runner error."""

    def __init__(self, exit_code: int, reason: str, message: str = "") -> None:
        super().__init__(message or reason)
        self.exit_code = exit_code
        self.reason = reason


def _record_ineligibility(
    provenance: dict[str, object],
    reason: str,
    exit_code: int,
) -> int:
    if (
        set(INELIGIBILITY_REASON_EXIT_FLOORS) != set(INELIGIBILITY_REASONS)
        or reason not in INELIGIBILITY_REASONS
        or exit_code not in EXIT_PRECEDENCE[2:]
        or EXIT_PRECEDENCE.index(exit_code)
        < EXIT_PRECEDENCE.index(INELIGIBILITY_REASON_EXIT_FLOORS[reason])
    ):
        raise RunnerError(72, "internal_invariant_failed")
    observed = provenance.get("ineligibility_reasons")
    if not isinstance(observed, list) or any(
        candidate not in INELIGIBILITY_REASONS for candidate in observed
    ):
        raise RunnerError(72, "internal_invariant_failed")
    reasons = sorted({*observed, reason})
    current = provenance.get("runner_exit_code")
    if observed:
        if type(current) is not int or current not in EXIT_PRECEDENCE:
            raise RunnerError(72, "internal_invariant_failed")
    else:
        current = 0
    selected = max(
        (int(current), exit_code),
        key=EXIT_PRECEDENCE.index,
    )
    provenance["eligible"] = False
    provenance["wall_gate"] = "ineligible"
    provenance["ineligibility_reasons"] = reasons
    provenance["runner_exit_code"] = selected
    return selected


