_CLEANUP_QUIESCENCE_SEAL = object()


@dataclass(frozen=True)
class CleanupQuiescence:
    scope: str
    owner_pid: int
    pid_namespace: int
    mount_namespace: int
    seal: object


def _mint_cleanup_quiescence(
    scope: str,
    *,
    lifecycle_proof: Mapping[str, object],
) -> CleanupQuiescence:
    if scope not in {
        "host",
        "host-evidence",
        "stage-a",
        "stage-b",
        "prelaunch",
        "self-test",
    }:
        raise RunnerError(70, "cleanup_identity_mismatch")
    if scope == "stage-a" and not all(
        lifecycle_proof.get(key) is True
        for key in (
            "echld_observed",
            "stage_b_reaped",
            "stage_b_process_teardown_proved",
            "stage_b_namespace_teardown_proved",
        )
    ):
        raise RunnerError(70, "cleanup_identity_mismatch")
    if scope == "stage-b" and lifecycle_proof.get("owned_child_reaped") is not True:
        raise RunnerError(70, "cleanup_identity_mismatch")
    if scope == "prelaunch" and lifecycle_proof.get("child_launch_attempted") is not False:
        raise RunnerError(70, "cleanup_identity_mismatch")
    if scope == "self-test" and lifecycle_proof.get("authenticated_self_test") is not True:
        raise RunnerError(70, "cleanup_identity_mismatch")
    if scope == "host":
        namespace = lifecycle_proof.get("namespace")
        if (
            not isinstance(namespace, Mapping)
            or namespace.get("stage_a_namespace_absent") is not True
        ):
            raise RunnerError(70, "cleanup_identity_mismatch")
    if (
        scope == "host-evidence"
        and lifecycle_proof.get("stage_a_process_teardown_proved") is not True
    ):
        raise RunnerError(70, "cleanup_identity_mismatch")
    owner_pid = os.getpid()
    if set(os.listdir("/proc/self/task")) != {str(owner_pid)}:
        raise RunnerError(70, "cleanup_identity_mismatch")
    return CleanupQuiescence(
        scope=scope,
        owner_pid=owner_pid,
        pid_namespace=os.stat("/proc/self/ns/pid").st_ino,
        mount_namespace=os.stat("/proc/self/ns/mnt").st_ino,
        seal=_CLEANUP_QUIESCENCE_SEAL,
    )


def _validate_cleanup_quiescence(authority: CleanupQuiescence | None) -> None:
    owner_pid = os.getpid()
    if (
        not isinstance(authority, CleanupQuiescence)
        or authority.seal is not _CLEANUP_QUIESCENCE_SEAL
        or authority.owner_pid != owner_pid
        or authority.pid_namespace != os.stat("/proc/self/ns/pid").st_ino
        or authority.mount_namespace != os.stat("/proc/self/ns/mnt").st_ino
        or set(os.listdir("/proc/self/task")) != {str(owner_pid)}
    ):
        raise RunnerError(70, "cleanup_identity_mismatch")


_PROTOCOL_UNLINK_SEAL = object()


@dataclass(frozen=True)
class ProtocolUnlinkAuthority:
    owner_pid: int
    pid_namespace: int
    mount_namespace: int
    seal: object


def _mint_protocol_unlink_authority() -> ProtocolUnlinkAuthority:
    owner_pid = os.getpid()
    if set(os.listdir("/proc/self/task")) != {str(owner_pid)}:
        raise RunnerError(68, "control_channel_invalid")
    return ProtocolUnlinkAuthority(
        owner_pid=owner_pid,
        pid_namespace=os.stat("/proc/self/ns/pid").st_ino,
        mount_namespace=os.stat("/proc/self/ns/mnt").st_ino,
        seal=_PROTOCOL_UNLINK_SEAL,
    )


def _validate_mutation_authority(
    authority: CleanupQuiescence | ProtocolUnlinkAuthority | None,
) -> None:
    if isinstance(authority, CleanupQuiescence):
        _validate_cleanup_quiescence(authority)
        return
    owner_pid = os.getpid()
    if (
        not isinstance(authority, ProtocolUnlinkAuthority)
        or authority.seal is not _PROTOCOL_UNLINK_SEAL
        or authority.owner_pid != owner_pid
        or authority.pid_namespace != os.stat("/proc/self/ns/pid").st_ino
        or authority.mount_namespace != os.stat("/proc/self/ns/mnt").st_ino
        or set(os.listdir("/proc/self/task")) != {str(owner_pid)}
    ):
        raise RunnerError(70, "cleanup_identity_mismatch")


def _host_cleanup_quiescence(
    provenance: Mapping[str, object],
) -> CleanupQuiescence:
    namespace = provenance.get("namespace")
    if isinstance(namespace, Mapping):
        if namespace.get("stage_a_namespace_absent") is True:
            return _mint_cleanup_quiescence(
                "host",
                lifecycle_proof=provenance,
            )
        if namespace.get("stage_a_bwrap_pid") is None:
            return _mint_cleanup_quiescence(
                "prelaunch",
                lifecycle_proof={"child_launch_attempted": False},
            )
    raise RunnerError(70, "cleanup_identity_mismatch")


