def write_provenance(partial_fd: int, provenance: Mapping[str, object]) -> dict[str, object]:
    _validate_provenance_record(provenance)
    data = (
        json.dumps(provenance, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        + "\n"
    ).encode("ascii")
    if len(data) > 8 * 1024 * 1024:
        raise RunnerError(71, "evidence_limit_exceeded")
    return _write_file_at(partial_fd, "provenance.json", data)


def write_preopened_provenance(
    partial_fd: int,
    provenance: Mapping[str, object],
) -> dict[str, object]:
    _validate_provenance_record(provenance)
    data = (
        json.dumps(provenance, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        + "\n"
    ).encode("ascii")
    if len(data) > 8 * 1024 * 1024:
        raise RunnerError(71, "evidence_limit_exceeded")
    return _rewrite_preopened_artifact(
        partial_fd,
        "provenance.json",
        data,
    )


def _rename_noreplace(
    old_parent_fd: int,
    old_name: str,
    new_parent_fd: int,
    new_name: str,
) -> None:
    result = _LIBC.renameat2(
        ctypes.c_int(old_parent_fd),
        ctypes.c_char_p(os.fsencode(old_name)),
        ctypes.c_int(new_parent_fd),
        ctypes.c_char_p(os.fsencode(new_name)),
        ctypes.c_uint(RENAME_NOREPLACE),
    )
    if result != 0:
        error = ctypes.get_errno()
        raise RunnerError(71, "evidence_write_failed", os.strerror(error))


def _open_artifact_authority(
    directory_fd: int,
    name: str,
) -> dict[str, object]:
    fd = os.open(
        name,
        os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
        dir_fd=directory_fd,
    )
    try:
        details = os.fstat(fd)
        mount_id = statx_identity(fd)[2]
        acl_sha256, foreign_write = read_effective_acl(fd)
        named_fd = os.open(
            name,
            os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=directory_fd,
        )
        try:
            named = os.fstat(named_fd)
            named_mount_id = statx_identity(named_fd)[2]
        finally:
            os.close(named_fd)
        digest = hash_open_file(fd)
        if (
            not stat.S_ISREG(details.st_mode)
            or details.st_uid != os.getuid()
            or stat.S_IMODE(details.st_mode) != 0o600
            or details.st_nlink != 1
            or foreign_write
            or (details.st_dev, details.st_ino)
            != (named.st_dev, named.st_ino)
            or named_mount_id != mount_id
        ):
            raise RunnerError(71, "evidence_write_failed")
        return {
            "name": name,
            "fd": fd,
            "identity": (details.st_dev, details.st_ino),
            "mount_id": mount_id,
            "bytes": details.st_size,
            "sha256": digest,
            "acl_sha256": acl_sha256,
        }
    except BaseException:
        os.close(fd)
        raise


def _revalidate_artifact_authorities(
    directory_fd: int,
    artifacts: Sequence[Mapping[str, object]],
) -> None:
    observed_names = set(os.listdir(directory_fd))
    expected_names = {str(artifact["name"]) for artifact in artifacts}
    if observed_names != expected_names:
        raise RunnerError(71, "evidence_write_failed")
    for artifact in artifacts:
        name = str(artifact["name"])
        fd = int(artifact["fd"])
        details = os.fstat(fd)
        held_mount_id = statx_identity(fd)[2]
        named_fd = os.open(
            name,
            os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=directory_fd,
        )
        try:
            named = os.fstat(named_fd)
            named_mount_id = statx_identity(named_fd)[2]
        finally:
            os.close(named_fd)
        acl_sha256, foreign_write = read_effective_acl(fd)
        if (
            (details.st_dev, details.st_ino) != artifact["identity"]
            or (named.st_dev, named.st_ino) != artifact["identity"]
            or held_mount_id != artifact["mount_id"]
            or named_mount_id != artifact["mount_id"]
            or details.st_size != artifact["bytes"]
            or not stat.S_ISREG(details.st_mode)
            or details.st_uid != os.getuid()
            or stat.S_IMODE(details.st_mode) != 0o600
            or details.st_nlink != 1
            or foreign_write
            or acl_sha256 != artifact["acl_sha256"]
            or hash_open_file(fd) != artifact["sha256"]
        ):
            raise RunnerError(71, "evidence_write_failed")


def _rollback_published_evidence_directory(
    authority: Mapping[str, object],
    directory_fd: int,
    directory_identity: DirectoryIdentity,
) -> None:
    parent_fd = int(authority["parent_fd"])
    partial_name = str(authority["partial_name"])
    final_name = str(authority["final_name"])
    revalidate_named_identity(
        parent_fd,
        final_name,
        directory_fd,
        directory_identity,
    )
    try:
        os.stat(partial_name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        pass
    else:
        raise RunnerError(71, "evidence_write_failed")
    _rename_noreplace(
        parent_fd,
        final_name,
        parent_fd,
        partial_name,
    )
    try:
        os.fsync(parent_fd)
    except OSError as error:
        raise RunnerError(71, "evidence_write_failed") from error
    revalidate_named_identity(
        parent_fd,
        partial_name,
        directory_fd,
        directory_identity,
    )


def _publish_evidence_directory(
    authority: Mapping[str, object],
    directory_fd: int,
    directory_identity: DirectoryIdentity,
    artifacts: Sequence[Mapping[str, object]],
) -> None:
    parent_fd = int(authority["parent_fd"])
    _rename_noreplace(
        parent_fd,
        str(authority["partial_name"]),
        parent_fd,
        str(authority["final_name"]),
    )
    try:
        revalidate_named_identity(
            parent_fd,
            str(authority["final_name"]),
            directory_fd,
            directory_identity,
        )
        final_fd = os.open(
            str(authority["final_name"]),
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=parent_fd,
        )
        try:
            _revalidate_artifact_authorities(final_fd, artifacts)
        finally:
            os.close(final_fd)
        os.fsync(parent_fd)
    except (OSError, RunnerError) as error:
        try:
            _rollback_published_evidence_directory(
                authority,
                directory_fd,
                directory_identity,
            )
        except RunnerError as rollback_error:
            raise RunnerError(71, "evidence_write_failed") from rollback_error
        if isinstance(error, RunnerError):
            raise
        raise RunnerError(71, "evidence_write_failed") from error


def finalize_after_stage_a_exit(
    authority: Mapping[str, object],
    provenance: dict[str, object],
) -> str:
    parent_fd = int(authority["parent_fd"])
    partial_fd = int(authority["partial_fd"])
    backing_fd = int(authority["backing_fd"])
    backing_identity = authority["backing_identity"]
    partial_identity = authority["partial_identity"]
    assert isinstance(backing_identity, DirectoryIdentity)
    assert isinstance(partial_identity, DirectoryIdentity)
    for ancestor_fd, ancestor_path, ancestor_identity in authority[
        "ancestor_records"
    ]:
        observed_ancestor = _directory_identity(int(ancestor_fd), str(ancestor_path))
        if observed_ancestor != ancestor_identity:
            raise RunnerError(70, "cleanup_identity_mismatch")
    parent_identity = authority["parent_identity"]
    assert isinstance(parent_identity, DirectoryIdentity)
    parent_post = _directory_identity(parent_fd, str(authority["parent_path"]))
    if parent_post != parent_identity:
        raise RunnerError(70, "cleanup_identity_mismatch")
    evidence_parent = provenance["mounts"].get("evidence_parent")
    if not isinstance(evidence_parent, dict):
        evidence_parent = {
            "pre": parent_identity.as_dict(),
            "post": None,
        }
        provenance["mounts"]["evidence_parent"] = evidence_parent
    evidence_parent["post"] = parent_post.as_dict()
    if not (
        provenance["namespace"]["stage_a_namespace_absent"]
        and provenance["containment"]["echld_observed"]
        and provenance["containment"]["authenticated_empty_record"]
        and provenance["containment"]["output_eof_after_stage_b_reap"]
        and provenance["containment"].get("output_overflow") is False
    ):
        raise RunnerError(70, "mount_teardown_failed")
    revalidate_named_identity(
        parent_fd,
        str(authority["partial_name"]),
        partial_fd,
        partial_identity,
    )
    _discard_unused_staged_artifacts(authority, provenance)
    artifact_authorities = _staged_artifact_authorities(authority)
    backing_post = _directory_identity(
        backing_fd,
        str(authority["backing_path"]),
    )
    if backing_post != backing_identity:
        raise RunnerError(70, "cleanup_identity_mismatch")
    if os.listdir(backing_fd):
        raise RunnerError(70, "mount_teardown_failed")
    revalidate_named_identity(
        parent_fd,
        str(authority["backing_name"]),
        backing_fd,
        backing_identity,
    )
    recovery_provenance = json.loads(
        json.dumps(provenance, sort_keys=True, separators=(",", ":"))
    )
    provenance["eligible"] = True
    provenance["record_stage"] = "complete"
    provenance["wall_gate"] = (
        "clean"
        if provenance.get("result", {}).get("canonical_match")
        else "regression"
    )
    provenance["runner_exit_code"] = 0 if provenance["wall_gate"] == "clean" else 69
    provenance["ineligibility_reasons"] = []
    provenance["finalized_at_utc"] = time.strftime(
        "%Y-%m-%dT%H:%M:%SZ",
        time.gmtime(),
    )
    expected_before_provenance = {
        "cargo.log",
        "containment.jsonl",
        "summary.json",
    }
    if provenance.get("result", {}).get("analysis_status") == "complete":
        expected_before_provenance.update(
            {
                "failure-names.txt",
                "normalized-signatures.txt",
            }
        )
    observed_before_provenance = set(os.listdir(partial_fd))
    if observed_before_provenance != expected_before_provenance | {
        "provenance.json"
    }:
        raise RunnerError(71, "evidence_write_failed")
    evidence_records = []
    for name in sorted(expected_before_provenance, key=os.fsencode):
        artifact = artifact_authorities.get(name)
        if not isinstance(artifact, dict):
            raise RunnerError(71, "evidence_write_failed")
        evidence_records.append(
            _revalidate_preopened_artifact(partial_fd, artifact)
        )
    provenance["evidence"] = evidence_records
    prospective = json.loads(
        json.dumps(provenance, sort_keys=True, separators=(",", ":"))
    )
    prospective["mounts"]["backing_mountpoint"].update(
        {
            "underlying_post": backing_post.as_dict(),
            "removed": True,
            "name_absence_proved": True,
            "descriptor_closed_after_absence": True,
        }
    )
    _validate_provenance_record(prospective)
    expected_artifacts = set(expected_before_provenance) | {"provenance.json"}
    artifacts: list[dict[str, object]] = []
    for name in sorted(expected_artifacts, key=os.fsencode):
        artifact = artifact_authorities.get(name)
        if not isinstance(artifact, dict):
            raise RunnerError(71, "evidence_write_failed")
        artifact.update(_revalidate_preopened_artifact(partial_fd, artifact))
        artifacts.append(artifact)
    os.fsync(partial_fd)
    revalidate_named_identity(
        parent_fd,
        str(authority["partial_name"]),
        partial_fd,
        partial_identity,
    )
    provenance_artifact = artifact_authorities.get("provenance.json")
    if not isinstance(provenance_artifact, dict):
        raise RunnerError(71, "evidence_write_failed")
    manifest_authority: dict[str, object] | None = None
    published = False
    try:
        _revalidate_artifact_authorities(partial_fd, artifacts)
        try:
            os.stat(
                str(authority["final_name"]),
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            raise RunnerError(71, "evidence_write_failed")
        backing_post = _directory_identity(
            backing_fd,
            str(authority["backing_path"]),
        )
        if backing_post != backing_identity:
            raise RunnerError(70, "cleanup_identity_mismatch")
        revalidate_named_identity(
            parent_fd,
            str(authority["backing_name"]),
            backing_fd,
            backing_identity,
        )
        remove_tree_at(
            parent_fd,
            str(authority["backing_name"]),
            expected=backing_post,
            cleanup_authority=_host_cleanup_quiescence(provenance),
        )
        if not isinstance(authority, dict):
            raise RunnerError(72, "internal_invariant_failed")
        authority["backing_removed"] = True
        authority["backing_post"] = backing_post
        os.close(backing_fd)
        authority["backing_fd"] = -1
        _rewrite_retained_json_artifact(
            partial_fd,
            provenance_artifact,
            prospective,
        )
        if set(os.listdir(partial_fd)) != expected_artifacts:
            raise RunnerError(71, "evidence_write_failed")
        provenance_artifact.update(
            _revalidate_preopened_artifact(partial_fd, provenance_artifact)
        )
        manifest = b"".join(
            f"{artifact['sha256']}  {artifact['name']}\n".encode("ascii")
            for artifact in sorted(
                artifacts,
                key=lambda value: os.fsencode(str(value["name"])),
            )
        )
        if len(manifest) > 1024 * 1024:
            raise RunnerError(71, "evidence_limit_exceeded")
        manifest_authority = _create_preopened_artifact_authority(
            partial_fd,
            "manifest.sha256",
        )
        _rewrite_retained_artifact(partial_fd, manifest_authority, manifest)
        artifacts.append(manifest_authority)
        os.fsync(partial_fd)
        _revalidate_artifact_authorities(partial_fd, artifacts)
        provenance.clear()
        provenance.update(prospective)
        _publish_evidence_directory(
            authority,
            partial_fd,
            partial_identity,
            artifacts,
        )
        published = True
    except BaseException as error:
        if manifest_authority is not None:
            try:
                _revalidate_preopened_artifact(
                    partial_fd,
                    manifest_authority,
                )
                unlink_validated_entry_at(
                    partial_fd,
                    "manifest.sha256",
                    expected=manifest_authority["identity"],
                    cleanup_authority=_host_cleanup_quiescence(provenance),
                )
            except BaseException as cleanup_error:
                raise RunnerError(
                    71,
                    "evidence_write_failed",
                ) from cleanup_error
            finally:
                manifest_fd = int(manifest_authority["fd"])
                if manifest_fd >= 0:
                    os.close(manifest_fd)
                    manifest_authority["fd"] = -1
                if manifest_authority in artifacts:
                    artifacts.remove(manifest_authority)
        if (
            isinstance(error, RunnerError)
            and error.reason in INELIGIBILITY_REASONS
            and error.exit_code in EXIT_PRECEDENCE[2:]
        ):
            recovery_error = error
        else:
            recovery_error = RunnerError(71, "evidence_write_failed")
        recovery_provenance["record_stage"] = "cleanup"
        recovery_provenance["finalized_at_utc"] = None
        _record_ineligibility(
            recovery_provenance,
            recovery_error.reason,
            recovery_error.exit_code,
        )
        _rewrite_retained_json_artifact(
            partial_fd,
            provenance_artifact,
            recovery_provenance,
        )
        provenance.clear()
        provenance.update(recovery_provenance)
        raise recovery_error from error
    finally:
        if published:
            for artifact in artifacts:
                artifact_fd = int(artifact["fd"])
                if artifact_fd >= 0:
                    os.close(artifact_fd)
                    artifact["fd"] = -1
    os.close(partial_fd)
    for ancestor_fd, _ancestor_path, _ancestor_identity in authority[
        "ancestor_records"
    ]:
        os.close(int(ancestor_fd))
    return os.path.join(
        str(authority["parent_path"]),
        str(authority["final_name"]),
    )


def _finalize_ineligible(
    authority: Mapping[str, object],
    provenance: dict[str, object],
    error: RunnerError,
    *,
    retain_backing: bool = False,
    stage_a_process_teardown_proved: bool = False,
) -> str:
    parent_fd = int(authority["parent_fd"])
    backing_fd = int(authority["backing_fd"])
    partial_fd = int(authority["partial_fd"])
    backing_identity = authority["backing_identity"]
    partial_identity = authority["partial_identity"]
    assert isinstance(backing_identity, DirectoryIdentity)
    assert isinstance(partial_identity, DirectoryIdentity)
    for ancestor_fd, ancestor_path, ancestor_identity in authority[
        "ancestor_records"
    ]:
        if (
            _directory_identity(int(ancestor_fd), str(ancestor_path))
            != ancestor_identity
        ):
            raise RunnerError(70, "cleanup_identity_mismatch")
    parent_identity = authority["parent_identity"]
    assert isinstance(parent_identity, DirectoryIdentity)
    parent_post = _directory_identity(parent_fd, str(authority["parent_path"]))
    if parent_post != parent_identity:
        raise RunnerError(70, "cleanup_identity_mismatch")
    revalidate_named_identity(
        parent_fd,
        str(authority["partial_name"]),
        partial_fd,
        partial_identity,
    )
    evidence_cleanup_authority = None
    if retain_backing:
        evidence_cleanup_authority = _mint_cleanup_quiescence(
            "host-evidence",
            lifecycle_proof={
                "stage_a_process_teardown_proved": (
                    stage_a_process_teardown_proved
                ),
            },
        )
    _discard_unused_staged_artifacts(
        authority,
        provenance,
        cleanup_authority=evidence_cleanup_authority,
    )
    artifact_authorities = _staged_artifact_authorities(authority)
    backing_retained = (
        retain_backing and authority.get("backing_removed") is not True
    )
    if authority.get("backing_removed") is True:
        backing_post = authority.get("backing_post")
        if not isinstance(backing_post, DirectoryIdentity):
            raise RunnerError(70, "cleanup_identity_mismatch")
        try:
            os.stat(
                str(authority["backing_name"]),
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            pass
        else:
            raise RunnerError(70, "cleanup_identity_mismatch")
    elif backing_retained:
        backing_post = _directory_identity(
            backing_fd,
            str(authority["backing_path"]),
        )
        if backing_post != backing_identity:
            raise RunnerError(70, "cleanup_identity_mismatch")
        revalidate_named_identity(
            parent_fd,
            str(authority["backing_name"]),
            backing_fd,
            backing_identity,
        )
    else:
        backing_post = _directory_identity(
            backing_fd,
            str(authority["backing_path"]),
        )
        if backing_post != backing_identity:
            raise RunnerError(70, "cleanup_identity_mismatch")
        if os.listdir(backing_fd):
            raise RunnerError(70, "cleanup_failed")
        revalidate_named_identity(
            parent_fd,
            str(authority["backing_name"]),
            backing_fd,
            backing_identity,
        )
        remove_tree_at(
            parent_fd,
            str(authority["backing_name"]),
            expected=backing_post,
            cleanup_authority=_host_cleanup_quiescence(provenance),
        )
        if not isinstance(authority, dict):
            raise RunnerError(72, "internal_invariant_failed")
        authority["backing_removed"] = True
        authority["backing_post"] = backing_post
        os.close(backing_fd)
        authority["backing_fd"] = -1
    _record_ineligibility(provenance, error.reason, error.exit_code)
    provenance["finalized_at_utc"] = time.strftime(
        "%Y-%m-%dT%H:%M:%SZ",
        time.gmtime(),
    )
    provenance["mounts"]["backing_mountpoint"].update(
        {
            "underlying_post": backing_post.as_dict(),
            "removed": not backing_retained,
            "name_absence_proved": not backing_retained,
            "descriptor_closed_after_absence": not backing_retained,
        }
    )
    evidence_parent = provenance["mounts"].get("evidence_parent")
    if not isinstance(evidence_parent, dict):
        evidence_parent = {
            "pre": parent_identity.as_dict(),
            "post": None,
        }
        provenance["mounts"]["evidence_parent"] = evidence_parent
    evidence_parent["post"] = parent_post.as_dict()
    observed_artifacts = set(os.listdir(partial_fd))
    if observed_artifacts != set(artifact_authorities):
        raise RunnerError(71, "evidence_write_failed")
    evidence_records = []
    for name in sorted(
        set(artifact_authorities) - {"provenance.json"},
        key=os.fsencode,
    ):
        evidence_records.append(
            _revalidate_preopened_artifact(
                partial_fd,
                artifact_authorities[name],
            )
        )
    provenance["evidence"] = evidence_records
    provenance_artifact = artifact_authorities["provenance.json"]
    _rewrite_retained_json_artifact(
        partial_fd,
        provenance_artifact,
        provenance,
    )
    held_artifacts: list[dict[str, object]] = []
    manifest_rows: list[tuple[str, str]] = []
    for name in sorted(artifact_authorities, key=os.fsencode):
        artifact = artifact_authorities[name]
        artifact.update(_revalidate_preopened_artifact(partial_fd, artifact))
        held_artifacts.append(artifact)
        manifest_rows.append((name, str(artifact["sha256"])))
    manifest = b"".join(
        f"{digest}  {name}\n".encode("ascii")
        for name, digest in manifest_rows
    )
    if len(manifest) > 1024 * 1024:
        raise RunnerError(71, "evidence_limit_exceeded")
    manifest_artifact = _create_preopened_artifact_authority(
        partial_fd,
        "manifest.sha256",
    )
    _rewrite_retained_artifact(partial_fd, manifest_artifact, manifest)
    held_artifacts.append(manifest_artifact)
    os.fsync(partial_fd)
    revalidate_named_identity(
        parent_fd,
        str(authority["partial_name"]),
        partial_fd,
        partial_identity,
    )
    try:
        _revalidate_artifact_authorities(partial_fd, held_artifacts)
        _publish_evidence_directory(
            authority,
            partial_fd,
            partial_identity,
            held_artifacts,
        )
    finally:
        for artifact in held_artifacts:
            artifact_fd = int(artifact["fd"])
            if artifact_fd >= 0:
                os.close(artifact_fd)
                artifact["fd"] = -1
    os.close(partial_fd)
    if backing_retained:
        os.close(backing_fd)
        if isinstance(authority, dict):
            authority["backing_fd"] = -1
    for ancestor_fd, _ancestor_path, _ancestor_identity in authority[
        "ancestor_records"
    ]:
        os.close(int(ancestor_fd))
    os.close(parent_fd)
    return os.path.join(
        str(authority["parent_path"]),
        str(authority["final_name"]),
    )


def _template_slots(template: Sequence[str]) -> set[str]:
    slots: set[str] = set()
    for element in template:
        if element in {BOOTSTRAP_V2_SOURCE, STAGE_BOOTSTRAP_SOURCE}:
            continue
        matches = re.findall(r"\{[A-Z0-9_-]+\}", element)
        for match in matches:
            if element != match:
                raise RunnerError(72, "internal_invariant_failed", "partial argv slot")
            if match in slots:
                raise RunnerError(72, "internal_invariant_failed", "duplicate argv slot")
            slots.add(match)
    return slots


def _substitute_template(
    template: Sequence[str],
    values: Mapping[str, str],
) -> tuple[str, ...]:
    expected = _template_slots(template)
    supplied = {"{" + key + "}" for key in values}
    if supplied != expected:
        raise RunnerError(72, "internal_invariant_failed", "argv slot mismatch")
    result = []
    for element in template:
        if element in expected:
            value = values[element[1:-1]]
            if "\0" in value:
                raise RunnerError(72, "internal_invariant_failed")
            result.append(value)
        else:
            result.append(element)
    return tuple(result)


def _template_sha256(template: Sequence[str]) -> str:
    return inline_sha256(_nul_frame(template))


class _NonDisclosingArgumentParser(argparse.ArgumentParser):
    def error(self, _message: str) -> None:
        raise RunnerError(64, "invocation_authority_invalid")


def parse_args(argv: Sequence[str]) -> dict[str, object]:
    if not argv:
        raise RunnerError(64, "invocation_authority_invalid")
    role = argv[0]
    if role not in {"host", "self-test", "stage-a", "stage-b-worker"}:
        raise RunnerError(64, "invocation_authority_invalid")
    parser = _NonDisclosingArgumentParser(
        add_help=False,
        allow_abbrev=False,
    )
    if role == "host":
        parser.add_argument("--mode", required=True, choices=("parallel", "serial"))
        parser.add_argument("--label", required=True)
        parser.add_argument("--timeout-seconds", required=True)
        parser.add_argument("--evidence-parent", required=True)
        parser.add_argument("--expected-head", required=True)
    elif role == "self-test":
        parser.add_argument("--evidence-parent", required=True)
        parser.add_argument("--expected-head", required=True)
    else:
        parser.add_argument("--mode", required=True, choices=("parallel", "serial"))
        parser.add_argument("--label", required=True)
        parser.add_argument("--timeout-seconds", required=True)
        parser.add_argument("--expected-head", required=True)
    try:
        namespace, extras = parser.parse_known_args(list(argv[1:]))
    except SystemExit as error:
        raise RunnerError(64, "invocation_authority_invalid") from error
    if extras:
        raise RunnerError(64, "invocation_authority_invalid")
    result = vars(namespace)
    result["role"] = role
    expected_head = result["expected_head"]
    if not isinstance(expected_head, str) or not re.fullmatch(
        r"[0-9a-f]{40}",
        expected_head,
    ):
        raise RunnerError(64, "invocation_authority_invalid")
    if role != "self-test":
        label = result["label"]
        if not isinstance(label, str) or not re.fullmatch(
            r"[a-z0-9][a-z0-9-]{0,63}",
            label,
        ):
            raise RunnerError(64, "invocation_authority_invalid")
        raw_timeout = result["timeout_seconds"]
        if not isinstance(raw_timeout, str) or not re.fullmatch(r"[0-9]+", raw_timeout):
            raise RunnerError(64, "invocation_authority_invalid")
        timeout = int(raw_timeout)
        if timeout < 1 or timeout > 21_600 or str(timeout) != raw_timeout:
            raise RunnerError(64, "invocation_authority_invalid")
        result["timeout_seconds"] = timeout
    if role in {"host", "self-test"}:
        evidence_parent = result["evidence_parent"]
        if (
            not isinstance(evidence_parent, str)
            or not os.path.isabs(evidence_parent)
            or os.path.normpath(evidence_parent) != evidence_parent
        ):
            raise RunnerError(64, "invocation_authority_invalid")
    return result


def _reject_product_home_selection(path: str) -> None:
    account_home = pwd.getpwuid(os.getuid()).pw_dir
    protected = {os.path.join(account_home, ".substrate")}
    ambient = os.environ.get("SUBSTRATE_HOME")
    if ambient and os.path.isabs(ambient):
        protected.add(os.path.normpath(ambient))
    for candidate in protected:
        try:
            common = os.path.commonpath((path, candidate))
        except ValueError:
            continue
        if common in {path, candidate}:
            raise RunnerError(67, "safe_parent_rejected")


def _verify_runtime_argv(arguments: Mapping[str, object]) -> str:
    role = str(arguments["role"])
    injected = globals().get("__CANONICAL_CMDLINE")
    if injected is None:
        with open("/proc/self/cmdline", "rb") as handle:
            raw = handle.read()
        fields = raw.split(b"\0")
        if fields[-1:] != [b""]:
            raise RunnerError(65, "invocation_authority_invalid")
        observed = tuple(os.fsdecode(field) for field in fields[:-1])
    else:
        if (
            not isinstance(injected, tuple)
            or not all(isinstance(field, bytes) for field in injected)
        ):
            raise RunnerError(65, "invocation_authority_invalid")
        observed = tuple(os.fsdecode(field) for field in injected)
    if role == "host":
        expected = _substitute_template(
            HOST_INVOCATION_ARGV_TEMPLATE_V1,
            {
                "MODE": str(arguments["mode"]),
                "LABEL": str(arguments["label"]),
                "TIMEOUT_DECIMAL": str(arguments["timeout_seconds"]),
                "EVIDENCE_PARENT": str(arguments["evidence_parent"]),
                "EXPECTED_HEAD": str(arguments["expected_head"]),
            },
        )
    elif role == "self-test":
        expected = (
            "/usr/bin/python3.13",
            "-I",
            "-S",
            "-B",
            "-c",
            BOOTSTRAP_V2_SOURCE,
            "self-test",
            "--evidence-parent",
            str(arguments["evidence_parent"]),
            "--expected-head",
            str(arguments["expected_head"]),
        )
    else:
        expected = (
            "/usr/bin/python3.13",
            "-I",
            "-S",
            "-B",
            "-c",
            STAGE_BOOTSTRAP_SOURCE,
            role,
            "--mode",
            str(arguments["mode"]),
            "--label",
            str(arguments["label"]),
            "--timeout-seconds",
            str(arguments["timeout_seconds"]),
            "--expected-head",
            str(arguments["expected_head"]),
        )
    if observed != expected:
        raise RunnerError(65, "invocation_authority_invalid")
    return inline_sha256(_nul_frame(observed))


def create_sealed_runner_memfd(source: bytes) -> int:
    fd = os.memfd_create(
        "substrate-canonical-wall-runner",
        os.MFD_CLOEXEC | os.MFD_ALLOW_SEALING,
    )
    try:
        _write_all(fd, source)
        seals = (
            fcntl.F_SEAL_SEAL
            | fcntl.F_SEAL_SHRINK
            | fcntl.F_SEAL_GROW
            | fcntl.F_SEAL_WRITE
        )
        fcntl.fcntl(fd, fcntl.F_ADD_SEALS, seals)
        if fcntl.fcntl(fd, fcntl.F_GET_SEALS) != seals:
            raise RunnerError(67, "invocation_authority_invalid")
        os.lseek(fd, 0, os.SEEK_SET)
        return fd
    except BaseException:
        os.close(fd)
        raise


@dataclass
class SpawnedProcess:
    pid: int
    pidfd: int


@dataclass
class PreparedAclUserNamespaces:
    stage_a_fd: int
    stage_b_fd: int


def close_prepared_acl_user_namespaces(
    namespaces: PreparedAclUserNamespaces,
) -> None:
    for descriptor in (namespaces.stage_a_fd, namespaces.stage_b_fd):
        try:
            os.close(descriptor)
        except OSError:
            pass


def _set_namespace_keeper_parent_death_signal() -> None:
    libc = ctypes.CDLL(None, use_errno=True)
    if libc.prctl(1, signal.SIGKILL, 0, 0, 0) != 0 or os.getppid() == 1:
        os._exit(127)


def _write_proc_id_map(path: str, data: bytes) -> None:
    descriptor = os.open(path, os.O_WRONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        _write_all(descriptor, data)
    finally:
        os.close(descriptor)


def _run_namespace_map_tool(executable_fd: int, argv: Sequence[str]) -> int:
    pid = os.fork()
    if pid == 0:
        try:
            devnull = os.open("/dev/null", os.O_RDWR | os.O_CLOEXEC)
            os.dup2(devnull, 0)
            os.dup2(devnull, 1)
            os.dup2(devnull, 2)
            if devnull > 2:
                os.close(devnull)
            _close_unpreserved_fds({0, 1, 2, executable_fd})
            os.execve(
                executable_fd,
                list(argv),
                {"LANG": "C.UTF-8", "LC_ALL": "C.UTF-8"},
            )
        except BaseException:
            os._exit(127)
    waited, raw_status = os.waitpid(pid, 0)
    if waited != pid:
        return 127
    return _decode_wait_status(raw_status)


def _acl_namespace_keeper_main(
    ready_write: int,
    mapped_read: int,
    stage_b_pid_write: int,
    release_read: int,
) -> None:
    _set_namespace_keeper_parent_death_signal()
    _close_unpreserved_fds(
        {0, 1, 2, ready_write, mapped_read, stage_b_pid_write, release_read}
    )
    os.unshare(os.CLONE_NEWUSER)
    if os.write(ready_write, b"R") != 1:
        os._exit(127)
    os.close(ready_write)
    if os.read(mapped_read, 1) != b"M":
        os._exit(127)
    os.close(mapped_read)
    stage_b_ready_read, stage_b_ready_write = os.pipe2(os.O_CLOEXEC)
    stage_b_mapped_read, stage_b_mapped_write = os.pipe2(os.O_CLOEXEC)
    stage_b_release_read, stage_b_release_write = os.pipe2(os.O_CLOEXEC)
    stage_b_pid = os.fork()
    if stage_b_pid == 0:
        try:
            _set_namespace_keeper_parent_death_signal()
            os.close(stage_b_ready_read)
            os.close(stage_b_mapped_write)
            os.close(stage_b_release_write)
            _close_unpreserved_fds(
                {
                    0,
                    1,
                    2,
                    stage_b_ready_write,
                    stage_b_mapped_read,
                    stage_b_release_read,
                }
            )
            os.unshare(os.CLONE_NEWUSER)
            if os.write(stage_b_ready_write, b"R") != 1:
                os._exit(127)
            os.close(stage_b_ready_write)
            if os.read(stage_b_mapped_read, 1) != b"M":
                os._exit(127)
            os.close(stage_b_mapped_read)
            if os.read(stage_b_release_read, 1) != b"X":
                os._exit(127)
            os.close(stage_b_release_read)
            os._exit(0)
        except BaseException:
            os._exit(127)
    os.close(stage_b_ready_write)
    os.close(stage_b_mapped_read)
    os.close(stage_b_release_read)
    if os.read(stage_b_ready_read, 1) != b"R":
        os._exit(127)
    os.close(stage_b_ready_read)
    _write_proc_id_map(f"/proc/{stage_b_pid}/setgroups", b"deny")
    _write_proc_id_map(
        f"/proc/{stage_b_pid}/uid_map",
        CANONICAL_STAGE_B_UID_MAP.encode("ascii"),
    )
    _write_proc_id_map(
        f"/proc/{stage_b_pid}/gid_map",
        CANONICAL_STAGE_B_GID_MAP.encode("ascii"),
    )
    if os.write(stage_b_mapped_write, b"M") != 1:
        os._exit(127)
    os.close(stage_b_mapped_write)
    if os.write(stage_b_pid_write, f"{stage_b_pid}\n".encode("ascii")) <= 0:
        os._exit(127)
    os.close(stage_b_pid_write)
    if os.read(release_read, 1) != b"X":
        os._exit(127)
    os.close(release_read)
    if os.write(stage_b_release_write, b"X") != 1:
        os._exit(127)
    os.close(stage_b_release_write)
    waited, raw_status = os.waitpid(stage_b_pid, 0)
    if waited != stage_b_pid or _decode_wait_status(raw_status) != 0:
        os._exit(127)
    os._exit(0)


def _acl_namespace_builder_main(
    endpoint_fd: int,
    newuidmap_fd: int,
    newgidmap_fd: int,
) -> None:
    endpoint = socket.socket(fileno=endpoint_fd)
    _set_namespace_keeper_parent_death_signal()
    _close_unpreserved_fds(
        {0, 1, 2, endpoint_fd, newuidmap_fd, newgidmap_fd}
    )
    ready_read, ready_write = os.pipe2(os.O_CLOEXEC)
    mapped_read, mapped_write = os.pipe2(os.O_CLOEXEC)
    stage_b_pid_read, stage_b_pid_write = os.pipe2(os.O_CLOEXEC)
    release_read, release_write = os.pipe2(os.O_CLOEXEC)
    keeper_pid = os.fork()
    if keeper_pid == 0:
        try:
            endpoint.close()
            os.close(ready_read)
            os.close(mapped_write)
            os.close(stage_b_pid_read)
            os.close(release_write)
            _acl_namespace_keeper_main(
                ready_write,
                mapped_read,
                stage_b_pid_write,
                release_read,
            )
        finally:
            os._exit(127)
    os.close(ready_write)
    os.close(mapped_read)
    os.close(stage_b_pid_write)
    os.close(release_read)
    try:
        if os.read(ready_read, 1) != b"R":
            raise RuntimeError
        os.close(ready_read)
        ready_read = -1
        uid_status = _run_namespace_map_tool(
            newuidmap_fd,
            (
                "/usr/bin/newuidmap",
                str(keeper_pid),
                "1000",
                "1000",
                "1",
                "1001",
                str(CANONICAL_SUBID_START),
                str(CANONICAL_ACL_ID_COUNT),
            ),
        )
        gid_status = _run_namespace_map_tool(
            newgidmap_fd,
            (
                "/usr/bin/newgidmap",
                str(keeper_pid),
                "1000",
                "1000",
                "1",
                "1001",
                str(CANONICAL_SUBID_START),
                str(CANONICAL_ACL_ID_COUNT),
            ),
        )
        if uid_status != 0 or gid_status != 0:
            raise RuntimeError
        if os.write(mapped_write, b"M") != 1:
            raise RuntimeError
        os.close(mapped_write)
        mapped_write = -1
        stage_b_pid_raw = os.read(stage_b_pid_read, 64)
        os.close(stage_b_pid_read)
        stage_b_pid_read = -1
        if not stage_b_pid_raw.endswith(b"\n"):
            raise RuntimeError
        stage_b_pid = int(stage_b_pid_raw[:-1])
        stage_a_fd = os.open(
            f"/proc/{keeper_pid}/ns/user",
            os.O_RDONLY | os.O_CLOEXEC,
        )
        stage_b_fd = os.open(
            f"/proc/{stage_b_pid}/ns/user",
            os.O_RDONLY | os.O_CLOEXEC,
        )
        try:
            stage_a_identity = os.fstat(stage_a_fd)
            stage_b_identity = os.fstat(stage_b_fd)
            payload = struct.pack(
                "!8sQQ",
                b"P1UNSV1\0",
                stage_a_identity.st_ino,
                stage_b_identity.st_ino,
            )
            sent = endpoint.sendmsg(
                [payload],
                [
                    (
                        socket.SOL_SOCKET,
                        socket.SCM_RIGHTS,
                        struct.pack("ii", stage_a_fd, stage_b_fd),
                    )
                ],
            )
            if sent != len(payload):
                raise RuntimeError
        finally:
            os.close(stage_a_fd)
            os.close(stage_b_fd)
        if os.write(release_write, b"X") != 1:
            raise RuntimeError
        os.close(release_write)
        release_write = -1
        waited, raw_status = os.waitpid(keeper_pid, 0)
        if waited != keeper_pid or _decode_wait_status(raw_status) != 0:
            raise RuntimeError
        endpoint.close()
        os._exit(0)
    except BaseException:
        try:
            endpoint.send(b"P1UNSERR")
        except OSError:
            pass
        try:
            os.write(release_write, b"X")
        except OSError:
            pass
        try:
            os.kill(keeper_pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        try:
            os.waitpid(keeper_pid, 0)
        except ChildProcessError:
            pass
        endpoint.close()
        os._exit(127)


def prepare_acl_user_namespaces(
    newuidmap: HeldExecutable,
    newgidmap: HeldExecutable,
) -> PreparedAclUserNamespaces:
    parent_endpoint, child_endpoint = socket.socketpair(
        socket.AF_UNIX,
        socket.SOCK_SEQPACKET | socket.SOCK_CLOEXEC,
    )
    helper_pid = os.fork()
    if helper_pid == 0:
        try:
            parent_endpoint.close()
            _acl_namespace_builder_main(
                child_endpoint.detach(),
                newuidmap.fd,
                newgidmap.fd,
            )
        finally:
            os._exit(127)
    child_endpoint.close()
    helper = SpawnedProcess(pid=helper_pid, pidfd=os.pidfd_open(helper_pid))
    received_fds: list[int] = []
    try:
        parent_endpoint.settimeout(SETUP_TIMEOUT_SECONDS)
        payload, ancillary, flags, _address = parent_endpoint.recvmsg(
            24,
            socket.CMSG_SPACE(2 * struct.calcsize("i")),
        )
        if flags & (socket.MSG_TRUNC | socket.MSG_CTRUNC):
            raise RunnerError(66, "environment_unavailable")
        for level, kind, data in ancillary:
            if level == socket.SOL_SOCKET and kind == socket.SCM_RIGHTS:
                if len(data) != 2 * struct.calcsize("i"):
                    raise RunnerError(66, "environment_unavailable")
                received_fds.extend(struct.unpack("ii", data))
        if len(received_fds) != 2 or len(set(received_fds)) != 2:
            raise RunnerError(66, "environment_unavailable")
        magic, stage_a_inode, stage_b_inode = struct.unpack("!8sQQ", payload)
        observed = tuple(os.fstat(descriptor).st_ino for descriptor in received_fds)
        if (
            magic != b"P1UNSV1\0"
            or observed != (stage_a_inode, stage_b_inode)
            or stage_a_inode == stage_b_inode
        ):
            raise RunnerError(66, "environment_unavailable")
        status = _reap_exact_spawned_before_deadline(
            helper,
            deadline=time.monotonic() + SETUP_TIMEOUT_SECONDS,
        )
        if status != 0:
            raise RunnerError(66, "environment_unavailable")
        os.close(helper.pidfd)
        parent_endpoint.close()
        for descriptor in received_fds:
            os.set_inheritable(descriptor, False)
        return PreparedAclUserNamespaces(
            stage_a_fd=received_fds[0],
            stage_b_fd=received_fds[1],
        )
    except BaseException as error:
        for descriptor in received_fds:
            try:
                os.close(descriptor)
            except OSError:
                pass
        parent_endpoint.close()
        try:
            _terminate_exact_spawned_process(helper)
        except BaseException:
            pass
        try:
            os.close(helper.pidfd)
        except OSError:
            pass
        if isinstance(error, RunnerError):
            raise
        raise RunnerError(66, "environment_unavailable") from error


def _reap_exact_spawned_before_deadline(
    spawned: SpawnedProcess,
    *,
    deadline: float,
) -> int:
    poller = selectors.DefaultSelector()
    try:
        poller.register(spawned.pidfd, selectors.EVENT_READ)
        remaining = deadline - time.monotonic()
        if remaining <= 0 or not poller.select(remaining):
            raise RunnerError(68, "containment_timeout")
    finally:
        poller.close()
    try:
        waitable = os.waitid(
            os.P_PIDFD,
            spawned.pidfd,
            os.WEXITED | os.WNOHANG | os.WNOWAIT,
        )
    except ChildProcessError as error:
        raise RunnerError(72, "internal_invariant_failed") from error
    if waitable is None:
        raise RunnerError(68, "containment_timeout")
    waited, raw_status = os.waitpid(spawned.pid, 0)
    if waited != spawned.pid:
        raise RunnerError(72, "internal_invariant_failed")
    return _decode_wait_status(raw_status)


def _force_kill_and_reap_spawned(
    spawned: SpawnedProcess,
    *,
    timeout_seconds: float = 5.0,
) -> int:
    deadline = time.monotonic() + timeout_seconds
    previous_mask = signal.pthread_sigmask(signal.SIG_BLOCK, {signal.SIGCHLD})
    try:
        try:
            _pidfd_send_signal(spawned.pidfd, signal.SIGKILL)
        except BaseException:
            # The retained pidfd and unreaped-child relationship prevent PID
            # recycling even when pidfd_send_signal itself is unavailable.
            try:
                os.kill(spawned.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
        while True:
            try:
                waitable = os.waitid(
                    os.P_PIDFD,
                    spawned.pidfd,
                    os.WEXITED | os.WNOHANG | os.WNOWAIT,
                )
            except ChildProcessError as error:
                raise RunnerError(72, "internal_invariant_failed") from error
            if waitable is not None:
                waited, raw_status = os.waitpid(spawned.pid, 0)
                if waited != spawned.pid:
                    raise RunnerError(72, "internal_invariant_failed")
                return _decode_wait_status(raw_status)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise RunnerError(68, "containment_timeout")
            try:
                signal.sigtimedwait({signal.SIGCHLD}, remaining)
            except InterruptedError:
                continue
    finally:
        signal.pthread_sigmask(signal.SIG_SETMASK, previous_mask)


def _terminate_exact_spawned_process(
    spawned: SpawnedProcess,
    *,
    term_seconds: float = 2.0,
    kill_seconds: float = 5.0,
) -> int:
    poller: selectors.BaseSelector | None = None
    try:
        poller = selectors.DefaultSelector()
        poller.register(spawned.pidfd, selectors.EVENT_READ)
        if not poller.select(0):
            _pidfd_send_signal(spawned.pidfd, signal.SIGTERM)
            if not poller.select(term_seconds):
                _pidfd_send_signal(spawned.pidfd, signal.SIGKILL)
                if not poller.select(kill_seconds):
                    raise RunnerError(68, "containment_timeout")
        waited, raw_status = os.waitpid(spawned.pid, 0)
        if waited != spawned.pid:
            raise RunnerError(72, "internal_invariant_failed")
        return _decode_wait_status(raw_status)
    except BaseException:
        return _force_kill_and_reap_spawned(
            spawned,
            timeout_seconds=kill_seconds,
        )
    finally:
        if poller is not None:
            poller.close()


def _spawn_held(
    executable_fd: int,
    argv: Sequence[str],
    env: Mapping[str, str],
    *,
    preserve_fds: Sequence[int] = (),
    stdout_fd: int | None = None,
    stderr_fd: int | None = None,
) -> SpawnedProcess:
    if signal.getsignal(signal.SIGCHLD) is not signal.SIG_DFL:
        raise RunnerError(68, "namespace_setup_failed")
    gate_read = -1
    gate_write = -1
    pid = -1
    spawned: SpawnedProcess | None = None
    try:
        gate_read, gate_write = os.pipe2(os.O_CLOEXEC)
        pid = os.fork()
        if pid == 0:
            try:
                if os.read(gate_read, 1) != b"G":
                    os._exit(127)
                os.close(gate_read)
                os.close(gate_write)
                if stdout_fd is not None:
                    os.dup2(stdout_fd, 1)
                if stderr_fd is not None:
                    os.dup2(stderr_fd, 2)
                keep = {
                    0,
                    1,
                    2,
                    executable_fd,
                    *preserve_fds,
                }
                os.set_inheritable(executable_fd, False)
                for fd in preserve_fds:
                    os.set_inheritable(fd, True)
                _close_unpreserved_fds(keep)
                os.execve(executable_fd, list(argv), dict(env))
            except BaseException:
                os._exit(127)
        descriptor = gate_read
        gate_read = -1
        os.close(descriptor)
        pidfd = os.pidfd_open(pid)
        spawned = SpawnedProcess(pid=pid, pidfd=pidfd)
        if os.write(gate_write, b"G") != 1:
            raise RunnerError(68, "namespace_setup_failed")
        descriptor = gate_write
        gate_write = -1
        os.close(descriptor)
        return spawned
    except BaseException as error:
        if spawned is not None:
            try:
                _terminate_exact_spawned_process(spawned)
            finally:
                os.close(spawned.pidfd)
        elif pid > 0:
            _kill_and_reap_gated_child(pid)
        if isinstance(error, RunnerError):
            raise
        raise RunnerError(68, "namespace_setup_failed") from error
    finally:
        for descriptor in (gate_read, gate_write):
            if descriptor >= 0:
                try:
                    os.close(descriptor)
                except OSError:
                    pass


def _read_fd_bounded(fd: int, limit: int, deadline: float) -> bytes:
    os.set_blocking(fd, False)
    output = bytearray()
    selector = selectors.DefaultSelector()
    selector.register(fd, selectors.EVENT_READ)
    try:
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise RunnerError(68, "stage_b_setup_timeout")
            events = selector.select(remaining)
            if not events:
                raise RunnerError(68, "stage_b_setup_timeout")
            chunk = os.read(fd, min(65_536, limit + 1 - len(output)))
            if not chunk:
                return bytes(output)
            output.extend(chunk)
            if len(output) > limit:
                raise RunnerError(68, "control_channel_invalid")
    finally:
        selector.close()


def _close_failed_launch_fds(descriptors: Sequence[int]) -> None:
    first_error: OSError | None = None
    for descriptor in descriptors:
        try:
            os.close(descriptor)
        except OSError as error:
            if first_error is None:
                first_error = error
    if first_error is not None:
        raise RunnerError(68, "namespace_setup_failed") from first_error


def launch_stage_a_bwrap(
    *,
    bwrap: HeldExecutable,
    user_namespaces: PreparedAclUserNamespaces,
    source: bytes,
    authority: Mapping[str, object],
    repository: str,
    rustup_source: str,
    cargo_source: str,
    mode: str,
    label: str,
    timeout_seconds: int,
    expected_head: str,
    environment: Mapping[str, str],
) -> tuple[SpawnedProcess, int, tuple[str, ...]]:
    runner_fd = -1
    status_read = -1
    status_write = -1
    spawned: SpawnedProcess | None = None
    completed = False
    try:
        runner_fd = create_sealed_runner_memfd(source)
        status_read, status_write = os.pipe2(os.O_CLOEXEC)
        values = {
            "MODE": mode,
            "LABEL": label,
            "TIMEOUT_DECIMAL": str(timeout_seconds),
            "CURRENT_UID_DECIMAL": str(os.getuid()),
            "CURRENT_GID_DECIMAL": str(os.getgid()),
            "STAGE_A_USERNS_FD_DECIMAL": str(user_namespaces.stage_a_fd),
            "STAGE_B_USERNS_SYNC_FD_DECIMAL": str(
                user_namespaces.stage_b_fd
            ),
            "RUNNER_DATA_FD_DECIMAL": str(runner_fd),
            "STATUS_FD_DECIMAL": str(status_write),
            "EVIDENCE_PARTIAL": str(authority["partial_path"]),
            "BACKING_PATH": str(authority["backing_path"]),
            "REPOSITORY_SOURCE": repository,
            "RUSTUP_SOURCE": rustup_source,
            "CARGO_SOURCE": cargo_source,
            "EXPECTED_HEAD": expected_head,
        }
        argv = _substitute_template(BWRAP_STAGE_A_ARGV_TEMPLATE_V1, values)
        spawned = _spawn_held(
            bwrap.fd,
            argv,
            environment,
            preserve_fds=(
                runner_fd,
                status_write,
                user_namespaces.stage_a_fd,
                user_namespaces.stage_b_fd,
            ),
        )
        descriptor = status_write
        status_write = -1
        os.close(descriptor)
        descriptor = runner_fd
        runner_fd = -1
        os.close(descriptor)
        completed = True
        return spawned, status_read, argv
    except BaseException:
        if spawned is not None:
            try:
                _terminate_exact_spawned_process(spawned)
            finally:
                os.close(spawned.pidfd)
        raise
    finally:
        failed_descriptors = tuple(
            descriptor
            for descriptor in (
                runner_fd,
                status_write,
                status_read if not completed else -1,
            )
            if descriptor >= 0
        )
        if failed_descriptors:
            _close_failed_launch_fds(failed_descriptors)


