def _validate_stage_b_projection_authority(
    arguments: Mapping[str, object],
) -> tuple[
    list[tuple[int, str, DirectoryIdentity]],
    dict[str, object],
    dict[str, object],
]:
    control_fd, control_identity = open_validated_directory(
        "/run/substrate-wall/control",
        expected_uid=os.getuid(),
        expected_mode=0o700,
        validate_ancestors=False,
    )
    held: list[tuple[int, str, DirectoryIdentity]] = []
    authority_fd: int | None = None
    try:
        authority_fd = os.open(
            "authority.json",
            os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
            dir_fd=control_fd,
        )
        authority_details = os.fstat(authority_fd)
        authority_acl_sha256, foreign_write = read_effective_acl(authority_fd)
        authority_raw = bytearray()
        while True:
            chunk = os.read(authority_fd, 65_536)
            if not chunk:
                break
            authority_raw.extend(chunk)
            if len(authority_raw) > 65_536:
                raise RunnerError(68, "invocation_authority_invalid")
        authority_named = os.stat(
            "authority.json",
            dir_fd=control_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(authority_details.st_mode)
            or authority_details.st_uid != os.getuid()
            or stat.S_IMODE(authority_details.st_mode) != 0o400
            or authority_details.st_nlink != 1
            or foreign_write
            or (authority_details.st_dev, authority_details.st_ino)
            != (authority_named.st_dev, authority_named.st_ino)
        ):
            raise RunnerError(68, "invocation_authority_invalid")
        try:
            authority = _json_no_duplicates(bytes(authority_raw))
        except (json.JSONDecodeError, ValueError) as error:
            raise RunnerError(68, "invocation_authority_invalid") from error
        if (
            not isinstance(authority, dict)
            or set(authority)
            != {
                "schema",
                "invocation_id",
                "runner_sha256",
                "expected_head",
                "mode",
                "label",
                "timeout_seconds",
                "projections",
            }
            or authority["schema"]
            != "substrate.canonical_shell_wall_stage_authority.v1"
            or authority["runner_sha256"]
            != globals().get("__CANONICAL_RUNNER_SHA256")
            or authority["expected_head"] != arguments["expected_head"]
            or authority["mode"] != arguments["mode"]
            or authority["label"] != arguments["label"]
            or authority["timeout_seconds"] != arguments["timeout_seconds"]
            or not isinstance(authority["invocation_id"], str)
            or not re.fullmatch(r"[0-9a-f]{32}", authority["invocation_id"])
            or not isinstance(authority["projections"], dict)
            or authority != globals().get("__CANONICAL_STAGE_AUTHORITY")
        ):
            raise RunnerError(68, "invocation_authority_invalid")
        expected_roles = {
            role for role, _path, _writable in _stage_b_projection_paths()
        }
        if set(authority["projections"]) != expected_roles:
            raise RunnerError(68, "invocation_authority_invalid")
        for role, path, writable in _stage_b_projection_paths():
            expected = authority["projections"][role]
            if (
                not isinstance(expected, dict)
                or set(expected) != {"dev", "ino", "mode", "uid", "writable"}
                or any(
                    type(expected[key]) is not int
                    for key in ("dev", "ino", "mode", "uid")
                )
                or type(expected["writable"]) is not bool
                or expected["writable"] is not writable
            ):
                raise RunnerError(68, "invocation_authority_invalid")
            descriptor, identity = open_validated_directory(
                path,
                expected_uid=int(expected["uid"]),
                expected_mode=int(expected["mode"]),
                validate_ancestors=False,
            )
            if (identity.dev, identity.ino) != (
                int(expected["dev"]),
                int(expected["ino"]),
            ):
                os.close(descriptor)
                raise RunnerError(68, "root_identity_drift")
            mount = _mountinfo_for_path(path)
            options = mount["options"]
            optional_fields = mount["optional_fields"]
            assert isinstance(options, list)
            assert isinstance(optional_fields, list)
            if (
                ("rw" in options) is not writable
                or ("ro" in options) is writable
                or any(
                    field.startswith(("shared:", "master:", "propagate_from:"))
                    for field in optional_fields
                )
            ):
                os.close(descriptor)
                raise RunnerError(68, "unexpected_mount")
            if int(mount["mount_id"]) != identity.mount_id:
                os.close(descriptor)
                raise RunnerError(68, "unexpected_mount")
            held.append((descriptor, path, identity))
        root_mount = _mountinfo_for_path("/")
        if (
            root_mount["fstype"] != "tmpfs"
            or root_mount["source"] != "tmpfs"
            or "ro" not in root_mount["options"]
            or "rw" in root_mount["options"]
            or any(
                field.startswith(("shared:", "master:", "propagate_from:"))
                for field in root_mount["optional_fields"]
            )
        ):
            raise RunnerError(68, "unexpected_mount")
        if (control_identity.dev, control_identity.ino) != (
            int(authority["projections"]["control"]["dev"]),
            int(authority["projections"]["control"]["ino"]),
        ):
            raise RunnerError(68, "root_identity_drift")
        authority_file = {
            "fd": authority_fd,
            "identity": (authority_details.st_dev, authority_details.st_ino),
            "bytes": authority_details.st_size,
            "sha256": inline_sha256(bytes(authority_raw)),
            "acl_sha256": authority_acl_sha256,
        }
        authority_fd = None
        os.close(control_fd)
        return held, authority, authority_file
    except BaseException:
        if authority_fd is not None:
            os.close(authority_fd)
        for descriptor, _path, _identity in held:
            os.close(descriptor)
        try:
            os.close(control_fd)
        except OSError:
            pass
        raise


def _revalidate_stage_b_projection_authority(
    held: Sequence[tuple[int, str, DirectoryIdentity]],
    authority_file: Mapping[str, object],
) -> None:
    control_descriptors = [
        descriptor
        for descriptor, path, _identity in held
        if path == "/run/substrate-wall/control"
    ]
    if len(control_descriptors) != 1:
        raise RunnerError(68, "root_identity_drift")
    authority_fd = int(authority_file["fd"])
    authority_details = os.fstat(authority_fd)
    authority_named = os.stat(
        "authority.json",
        dir_fd=control_descriptors[0],
        follow_symlinks=False,
    )
    authority_acl_sha256, authority_foreign_write = read_effective_acl(
        authority_fd
    )
    if (
        (authority_details.st_dev, authority_details.st_ino)
        != authority_file["identity"]
        or (authority_named.st_dev, authority_named.st_ino)
        != authority_file["identity"]
        or authority_details.st_size != authority_file["bytes"]
        or authority_details.st_nlink != 1
        or authority_foreign_write
        or authority_acl_sha256 != authority_file["acl_sha256"]
        or hash_open_file(authority_fd) != authority_file["sha256"]
    ):
        raise RunnerError(68, "invocation_authority_invalid")
    for descriptor, path, identity in held:
        observed = _directory_identity(descriptor, path)
        if (
            (observed.dev, observed.ino, observed.uid, observed.mode)
            != (identity.dev, identity.ino, identity.uid, identity.mode)
            or observed.acl_sha256 != identity.acl_sha256
            or observed.foreign_effective_write
            or not observed.path_matches_fd
            or _mountinfo_for_path(path)["mount_id"] != observed.mount_id
        ):
            raise RunnerError(68, "root_identity_drift")


def stage_b_worker_main(arguments: Mapping[str, object]) -> int:
    if os.getpid() != 1 or os.getppid() != 0:
        raise RunnerError(68, "namespace_setup_failed")
    _validate_current_user_namespace_maps("stage-b")
    if not set_child_subreaper():
        raise RunnerError(68, "subreaper_unverified")
    pid_namespace_inode = os.stat("/proc/self/ns/pid").st_ino
    projection_fds, _stage_authority, authority_file = (
        _validate_stage_b_projection_authority(arguments)
    )
    _validate_stage_b_home_projection()
    _validate_stage_b_account_projection()
    control_path = "/run/substrate-wall/control/worker.sock"
    endpoint = socket.socket(
        socket.AF_UNIX,
        socket.SOCK_SEQPACKET | socket.SOCK_CLOEXEC,
    )
    setup_deadline = time.monotonic() + SETUP_TIMEOUT_SECONDS
    try:
        endpoint.settimeout(max(0.001, setup_deadline - time.monotonic()))
        try:
            endpoint.connect(control_path)
        except (TimeoutError, socket.timeout) as error:
            raise RunnerError(68, "worker_handshake_failed") from error
        endpoint.set_inheritable(False)
        endpoint.sendall(READY_RECORD)
        endpoint.settimeout(max(0.001, setup_deadline - time.monotonic()))
        try:
            start = endpoint.recv(2)
        except (TimeoutError, socket.timeout) as error:
            raise RunnerError(68, "worker_handshake_failed") from error
        if start != START_RECORD:
            raise RunnerError(68, "worker_handshake_failed")
        timeout_seconds = int(arguments["timeout_seconds"])
        wall_deadline = time.monotonic() + timeout_seconds
        endpoint.settimeout(None)
        try:
            os.stat(control_path, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise RunnerError(68, "control_channel_invalid")
        mode = str(arguments["mode"])
        command = _canonical_cargo_command(mode)
        environment = dict(os.environ)
        tmpdir = environment.get("TMPDIR")
        xdg_runtime = environment.get("XDG_RUNTIME_DIR")
        if (
            not tmpdir
            or not xdg_runtime
            or not os.path.isabs(tmpdir)
            or not os.path.isabs(xdg_runtime)
        ):
            raise RunnerError(68, "root_validation_failed")
    except BaseException:
        endpoint.close()
        for descriptor, _path, _identity in projection_fds:
            os.close(descriptor)
        os.close(int(authority_file["fd"]))
        raise
    primary_pid: int | None = None
    primary_pidfd: int | None = None
    projected_rustup: HeldExecutable | None = None
    received_signals: list[int] = []

    def forward(received: int, _frame: object) -> None:
        if received not in received_signals:
            received_signals.append(received)
        if primary_pidfd is not None:
            try:
                _pidfd_send_signal(primary_pidfd, received)
            except OSError:
                pass
        os.kill(os.getpid(), signal.SIGCHLD)

    previous_handlers = {
        number: signal.signal(number, forward)
        for number in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP)
    }
    try:
        projected_rustup = _verify_projected_toolchain(environment)
        if time.monotonic() >= wall_deadline:
            raise RunnerError(68, "containment_timeout")
        primary_pid = _spawn_primary_command(
            command,
            environment,
            projected_rustup,
        )
        primary_pidfd = os.pidfd_open(primary_pid)
        result = wait_for_containment_empty(
            primary_pid,
            wall_deadline,
            expected_pid_namespace_inode=pid_namespace_inode,
            cancelled=lambda: bool(received_signals),
        )
        _revalidate_stage_b_projection_authority(
            projection_fds,
            authority_file,
        )
        if (
            projected_rustup is None
            or hash_open_file(projected_rustup.fd) != projected_rustup.sha256
        ):
            raise RunnerError(68, "executable_identity_drift")
        containment_empty = (
            result.echld_observed
            and not result.timed_out
            and not result.survivors
            and not received_signals
        )
        payload = {
            "schema": STATUS_VERSION,
            "discriminator": (
                "CONTAINMENT_EMPTY"
                if containment_empty
                else "CONTAINMENT_INELIGIBLE"
            ),
            "pid_namespace_inode": pid_namespace_inode,
            "primary_pid": primary_pid,
            "primary_status": result.primary_status,
            "reaped_descendants": result.reaped_descendants,
            "echld_observed": result.echld_observed,
            "timed_out": result.timed_out,
            "forced_teardown": result.forced_teardown,
            "survivors": list(result.survivors),
            "received_signals": received_signals,
        }
        _validate_worker_result(payload)
        _send_frame(endpoint, payload)
        endpoint.shutdown(socket.SHUT_WR)
        endpoint.settimeout(CLEANUP_TIMEOUT_SECONDS)
        try:
            release = endpoint.recv(1)
        except (TimeoutError, socket.timeout) as error:
            raise RunnerError(71, "evidence_write_failed") from error
        if release != b"":
            raise RunnerError(68, "control_channel_invalid")
        if not containment_empty:
            return 68
        if result.primary_status is None:
            return 68
        return 0
    finally:
        if primary_pidfd is not None:
            os.close(primary_pidfd)
        if projected_rustup is not None:
            os.close(projected_rustup.fd)
        endpoint.close()
        for number, handler in previous_handlers.items():
            signal.signal(number, handler)
        for descriptor, _path, _identity in projection_fds:
            os.close(descriptor)
        os.close(int(authority_file["fd"]))


