def retain_cargo_search_path_absence(
    *,
    repository: str = REPOSITORY_CANONICAL_PATH,
    account: str = "/home/spenser",
) -> list[dict[str, object]]:
    bases = (
        repository,
        os.path.dirname(repository),
        account,
    )
    authority: list[dict[str, object]] = []
    try:
        for base in bases:
            base_mode = stat.S_IMODE(
                os.stat(base, follow_symlinks=False).st_mode
            )
            base_fd, base_identity = open_validated_directory(
                base,
                expected_uid=os.getuid(),
                expected_mode=base_mode,
            )
            record: dict[str, object] = {
                "base": base,
                "base_fd": base_fd,
                "base_identity": base_identity,
                "cargo_fd": None,
                "cargo_identity": None,
                "names": (
                    ("config", "config.toml", "credentials", "credentials.toml")
                    if base == account
                    else ("config", "config.toml")
                ),
            }
            authority.append(record)
            try:
                cargo_details = os.stat(
                    ".cargo",
                    dir_fd=base_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                record["cargo_absent"] = True
            else:
                if not stat.S_ISDIR(cargo_details.st_mode):
                    raise RunnerError(65, "repository_identity_mismatch")
                cargo_path = os.path.join(base, ".cargo")
                cargo_fd, cargo_identity = open_validated_directory(
                    cargo_path,
                    expected_uid=os.getuid(),
                    expected_mode=stat.S_IMODE(cargo_details.st_mode),
                )
                record.update(
                    {
                        "cargo_absent": False,
                        "cargo_fd": cargo_fd,
                        "cargo_identity": cargo_identity,
                    }
                )
                for name in record["names"]:
                    try:
                        os.stat(
                            str(name),
                            dir_fd=cargo_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        continue
                    raise RunnerError(65, "repository_identity_mismatch")
        return authority
    except BaseException:
        close_cargo_search_path_authority(authority)
        raise


def revalidate_cargo_search_path_absence(
    authority: Sequence[Mapping[str, object]],
) -> None:
    if len(authority) != 3:
        raise RunnerError(65, "repository_identity_mismatch")
    for record in authority:
        base_fd = int(record["base_fd"])
        base = str(record["base"])
        if _directory_identity(base_fd, base) != record["base_identity"]:
            raise RunnerError(65, "repository_identity_mismatch")
        cargo_fd = record["cargo_fd"]
        if cargo_fd is None:
            try:
                os.stat(
                    ".cargo",
                    dir_fd=base_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                continue
            raise RunnerError(65, "repository_identity_mismatch")
        cargo_path = os.path.join(base, ".cargo")
        if (
            _directory_identity(int(cargo_fd), cargo_path)
            != record["cargo_identity"]
        ):
            raise RunnerError(65, "repository_identity_mismatch")
        for name in record["names"]:
            try:
                os.stat(
                    str(name),
                    dir_fd=int(cargo_fd),
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                continue
            raise RunnerError(65, "repository_identity_mismatch")


def close_cargo_search_path_authority(
    authority: Sequence[Mapping[str, object]],
) -> None:
    for record in authority:
        for key in ("cargo_fd", "base_fd"):
            descriptor = record.get(key)
            if descriptor is None:
                continue
            try:
                os.close(int(descriptor))
            except OSError:
                pass


def _read_json_file_at(directory_fd: int, name: str) -> dict[str, object]:
    fd = os.open(name, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW, dir_fd=directory_fd)
    try:
        details = os.fstat(fd)
        named = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        acl_sha256, foreign_write = read_effective_acl(fd)
        if (
            not stat.S_ISREG(details.st_mode)
            or details.st_uid != os.getuid()
            or stat.S_IMODE(details.st_mode) != 0o600
            or details.st_nlink != 1
            or details.st_size > 8 * 1024 * 1024
            or foreign_write
            or (details.st_dev, details.st_ino)
            != (named.st_dev, named.st_ino)
        ):
            raise RunnerError(71, "evidence_write_failed")
        data = bytearray()
        while True:
            chunk = os.read(fd, 65_536)
            if not chunk:
                break
            data.extend(chunk)
        after = os.fstat(fd)
        named_after = os.stat(
            name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        acl_after, foreign_write_after = read_effective_acl(fd)
        if (
            (after.st_dev, after.st_ino, after.st_size)
            != (details.st_dev, details.st_ino, details.st_size)
            or len(data) != details.st_size
            or (named_after.st_dev, named_after.st_ino)
            != (details.st_dev, details.st_ino)
            or acl_after != acl_sha256
            or foreign_write_after
        ):
            raise RunnerError(71, "evidence_write_failed")
    finally:
        os.close(fd)
    try:
        value = _json_no_duplicates(bytes(data))
    except (json.JSONDecodeError, ValueError) as error:
        raise RunnerError(71, "evidence_write_failed") from error
    if not isinstance(value, dict):
        raise RunnerError(71, "evidence_write_failed")
    return value


def _rewrite_json_file_at(
    directory_fd: int,
    name: str,
    value: Mapping[str, object],
) -> None:
    data = (
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True)
        + "\n"
    ).encode("ascii")
    if len(data) > 8 * 1024 * 1024:
        raise RunnerError(71, "evidence_limit_exceeded")
    fd = os.open(
        name,
        os.O_RDWR | os.O_CLOEXEC | os.O_NOFOLLOW,
        dir_fd=directory_fd,
    )
    try:
        details = os.fstat(fd)
        named = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        acl_sha256, foreign_write = read_effective_acl(fd)
        if (
            not stat.S_ISREG(details.st_mode)
            or details.st_uid != os.getuid()
            or stat.S_IMODE(details.st_mode) != 0o600
            or details.st_nlink != 1
            or foreign_write
            or (details.st_dev, details.st_ino)
            != (named.st_dev, named.st_ino)
        ):
            raise RunnerError(71, "evidence_write_failed")
        os.ftruncate(fd, 0)
        os.lseek(fd, 0, os.SEEK_SET)
        _write_all(fd, data)
        os.fsync(fd)
        after = os.fstat(fd)
        named_after = os.stat(
            name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        acl_after, foreign_write_after = read_effective_acl(fd)
        if (
            (after.st_dev, after.st_ino) != (details.st_dev, details.st_ino)
            or (named_after.st_dev, named_after.st_ino)
            != (details.st_dev, details.st_ino)
            or after.st_size != len(data)
            or stat.S_IMODE(after.st_mode) != 0o600
            or after.st_nlink != 1
            or acl_after != acl_sha256
            or foreign_write_after
            or hash_open_file(fd) != inline_sha256(data)
        ):
            raise RunnerError(71, "evidence_write_failed")
    finally:
        os.close(fd)


def _verify_commit_trailers(commit: bytes) -> None:
    separator = commit.find(b"\n\n")
    if separator < 0:
        raise RunnerError(65, "invocation_authority_invalid")
    message = commit[separator + 2 :].decode("utf-8", "strict")
    expected = {
        "P1-Bootstrap-Bytes": str(len(BOOTSTRAP_V2_SOURCE.encode("utf-8"))),
        "P1-Bootstrap-SHA256": inline_sha256(BOOTSTRAP_V2_SOURCE.encode("utf-8")),
        "P1-Host-Argv-Template-SHA256": _template_sha256(
            HOST_INVOCATION_ARGV_TEMPLATE_V1
        ),
        "P1-Stage-A-Argv-Template-SHA256": _template_sha256(
            BWRAP_STAGE_A_ARGV_TEMPLATE_V1
        ),
        "P1-Stage-B-Argv-Template-SHA256": _template_sha256(
            BWRAP_STAGE_B_ARGV_TEMPLATE_V1
        ),
    }
    observed: dict[str, str] = {}
    for line in message.splitlines():
        key, separator, value = line.partition(": ")
        if separator and key in expected:
            if key in observed:
                raise RunnerError(65, "invocation_authority_invalid")
            observed[key] = value
    if observed != expected:
        raise RunnerError(65, "invocation_authority_invalid")


def _process_start_time_ticks(pid: int) -> int:
    with open(f"/proc/{pid}/stat", "rb") as handle:
        raw = handle.read()
    close = raw.rfind(b")")
    if close < 0:
        raise RunnerError(68, "stage_a_liveness_failed")
    fields = raw[close + 2 :].split()
    return int(fields[19])


def _namespace_references(
    namespace: str,
    inode: int,
    *,
    inaccessible_exemptions: Mapping[int, int] | None = None,
) -> tuple[str, ...]:
    if namespace not in {"pid", "mnt"} or inode <= 0:
        raise RunnerError(70, "mount_teardown_failed")
    targets = {f"{namespace}:[{inode}]"}
    namespace_entries = (
        ("pid", "pid_for_children") if namespace == "pid" else ("mnt",)
    )
    references: list[str] = []
    exemptions = (
        dict(inaccessible_exemptions)
        if inaccessible_exemptions is not None
        else {}
    )
    for entry in sorted(os.listdir("/proc")):
        if not entry.isdigit():
            continue
        process_root = os.path.join("/proc", entry)
        try:
            process_uid = os.stat(process_root, follow_symlinks=False).st_uid
        except FileNotFoundError:
            continue
        if process_uid != os.getuid():
            continue
        task_root = os.path.join(process_root, "task")
        try:
            process_start = _process_start_time_ticks(int(entry))
            tasks = os.listdir(task_root)
        except FileNotFoundError:
            continue
        except PermissionError as error:
            if exemptions.get(int(entry)) == process_start:
                continue
            raise RunnerError(70, "mount_teardown_failed") from error
        permission_denied = False
        for task in tasks:
            thread_root = os.path.join(task_root, task)
            for namespace_entry in namespace_entries:
                path = os.path.join(thread_root, "ns", namespace_entry)
                try:
                    target = os.readlink(path)
                except FileNotFoundError:
                    continue
                except PermissionError:
                    permission_denied = True
                    continue
                if target in targets:
                    references.append(path)
            descriptor_root = os.path.join(thread_root, "fd")
            try:
                descriptors = os.listdir(descriptor_root)
            except FileNotFoundError:
                continue
            except PermissionError:
                permission_denied = True
                continue
            for descriptor in descriptors:
                path = os.path.join(descriptor_root, descriptor)
                try:
                    target = os.readlink(path)
                except FileNotFoundError:
                    continue
                except PermissionError:
                    permission_denied = True
                    continue
                if target in targets:
                    references.append(path)
        if (
            permission_denied
            and exemptions.get(int(entry)) != process_start
        ):
            raise RunnerError(70, "mount_teardown_failed")
    return tuple(references)


def _namespace_reference_census(
    *,
    inaccessible_exemptions: Mapping[int, int] | None = None,
) -> frozenset[tuple[str, int]]:
    references: set[tuple[str, int]] = set()
    exemptions = (
        dict(inaccessible_exemptions)
        if inaccessible_exemptions is not None
        else {}
    )
    for entry in sorted(os.listdir("/proc")):
        if not entry.isdigit():
            continue
        process_root = os.path.join("/proc", entry)
        process_start: int | None = None
        try:
            if (
                os.stat(process_root, follow_symlinks=False).st_uid
                != os.getuid()
            ):
                continue
            process_start = _process_start_time_ticks(int(entry))
            tasks = os.listdir(os.path.join(process_root, "task"))
        except FileNotFoundError:
            continue
        except PermissionError as error:
            if (
                process_start is not None
                and exemptions.get(int(entry)) == process_start
            ):
                continue
            raise RunnerError(70, "mount_teardown_failed") from error
        permission_denied = False
        for task in tasks:
            thread_root = os.path.join(process_root, "task", task)
            paths: list[str] = [
                os.path.join(thread_root, "ns", namespace_entry)
                for namespace_entry in ("pid", "pid_for_children", "mnt")
            ]
            descriptor_root = os.path.join(thread_root, "fd")
            try:
                paths.extend(
                    os.path.join(descriptor_root, descriptor)
                    for descriptor in os.listdir(descriptor_root)
                )
            except FileNotFoundError:
                pass
            except PermissionError:
                permission_denied = True
            for path in paths:
                try:
                    target = os.readlink(path)
                except FileNotFoundError:
                    continue
                except PermissionError:
                    permission_denied = True
                    continue
                match = re.fullmatch(r"(pid|mnt):\[([0-9]+)\]", target)
                if match is not None:
                    references.add((match.group(1), int(match.group(2))))
        if permission_denied and exemptions.get(int(entry)) != process_start:
            raise RunnerError(70, "mount_teardown_failed")
    return frozenset(references)


def _verify_spawned_namespace_boundary_teardown(
    spawned: SpawnedProcess,
    baseline: frozenset[tuple[str, int]],
    *,
    inaccessible_exemptions: Mapping[int, int] | None = None,
) -> None:
    if not isinstance(baseline, frozenset) or any(
        namespace not in {"pid", "mnt"} or type(inode) is not int or inode <= 0
        for namespace, inode in baseline
    ):
        raise RunnerError(72, "internal_invariant_failed")
    poller = selectors.DefaultSelector()
    try:
        poller.register(spawned.pidfd, selectors.EVENT_READ)
        if not poller.select(CLEANUP_TIMEOUT_SECONDS):
            raise RunnerError(70, "mount_teardown_failed")
    finally:
        poller.close()
    if any(
        os.path.exists(f"/proc/{spawned.pid}/ns/{name}")
        for name in ("pid", "mnt")
    ):
        raise RunnerError(70, "mount_teardown_failed")
    observed = _namespace_reference_census(
        inaccessible_exemptions=inaccessible_exemptions,
    )
    if not observed.issubset(baseline):
        raise RunnerError(70, "mount_teardown_failed")


def _capture_inaccessible_namespace_scan_exemptions() -> dict[int, int]:
    exemptions: dict[int, int] = {}
    for entry in sorted(os.listdir("/proc")):
        if not entry.isdigit():
            continue
        process_root = os.path.join("/proc", entry)
        try:
            if (
                os.stat(process_root, follow_symlinks=False).st_uid
                != os.getuid()
            ):
                continue
            process_start = _process_start_time_ticks(int(entry))
            tasks = os.listdir(os.path.join(process_root, "task"))
            for task in tasks:
                thread_root = os.path.join(process_root, "task", task)
                for namespace_entry in ("pid", "pid_for_children", "mnt"):
                    try:
                        os.readlink(
                            os.path.join(thread_root, "ns", namespace_entry)
                        )
                    except FileNotFoundError:
                        continue
                descriptor_root = os.path.join(thread_root, "fd")
                for descriptor in os.listdir(descriptor_root):
                    try:
                        os.readlink(os.path.join(descriptor_root, descriptor))
                    except FileNotFoundError:
                        continue
        except FileNotFoundError:
            continue
        except PermissionError:
            exemptions[int(entry)] = process_start
    return exemptions


def verify_namespace_mount_teardown(
    pid: int,
    pidfd: int,
    *,
    expected_start_time: int | None,
    expected_namespace_inodes: Mapping[str, int],
    inaccessible_exemptions: Mapping[int, int] | None = None,
) -> bool:
    try:
        current_start = _process_start_time_ticks(pid)
    except FileNotFoundError:
        current_start = None
    if current_start is not None and (
        expected_start_time is None or current_start != expected_start_time
    ):
        raise RunnerError(70, "mount_teardown_failed")
    poller = selectors.DefaultSelector()
    poller.register(pidfd, selectors.EVENT_READ)
    try:
        if not poller.select(CLEANUP_TIMEOUT_SECONDS):
            raise RunnerError(70, "mount_teardown_failed")
    finally:
        poller.close()
    for namespace in ("pid", "mnt"):
        if os.path.exists(f"/proc/{pid}/ns/{namespace}"):
            raise RunnerError(70, "mount_teardown_failed")
    verify_namespace_inodes_absent(
        expected_namespace_inodes,
        inaccessible_exemptions=inaccessible_exemptions,
    )
    return True


def verify_namespace_inodes_absent(
    expected_namespace_inodes: Mapping[str, int],
    *,
    inaccessible_exemptions: Mapping[int, int] | None = None,
) -> None:
    if set(expected_namespace_inodes) != {"pid", "mnt"}:
        raise RunnerError(70, "mount_teardown_failed")
    for namespace in ("pid", "mnt"):
        inode = expected_namespace_inodes.get(namespace)
        if (
            type(inode) is not int
            or inode <= 0
            or _namespace_references(
                namespace,
                inode,
                inaccessible_exemptions=inaccessible_exemptions,
            )
        ):
            raise RunnerError(70, "mount_teardown_failed")


def _captured_stage_b_namespace_inodes(
    provenance: Mapping[str, object],
) -> dict[str, int] | None:
    namespace = provenance.get("namespace")
    if not isinstance(namespace, dict):
        return None
    pid_inode = namespace.get("stage_b_pid_namespace_inode")
    mount_inode = namespace.get("stage_b_mount_namespace_inode")
    if pid_inode is None and mount_inode is None:
        return None
    if (
        type(pid_inode) is not int
        or pid_inode <= 0
        or type(mount_inode) is not int
        or mount_inode <= 0
    ):
        raise RunnerError(70, "mount_teardown_failed")
    return {"pid": pid_inode, "mnt": mount_inode}


def validate_containment_jsonl(data: bytes) -> None:
    if len(data) > MAX_CONTAINMENT_BYTES:
        raise RunnerError(71, "evidence_limit_exceeded")
    if not data or not data.endswith(b"\n") or b"\r" in data:
        raise RunnerError(71, "evidence_write_failed")
    lines = data.splitlines(keepends=True)
    if len(lines) > MAX_CONTAINMENT_EVENTS:
        raise RunnerError(71, "evidence_limit_exceeded")
    for sequence, line in enumerate(lines):
        if len(line) > MAX_CONTAINMENT_LINE_BYTES:
            raise RunnerError(71, "evidence_limit_exceeded")
        if not line.endswith(b"\n") or line == b"\n":
            raise RunnerError(71, "evidence_write_failed")
        try:
            value = _json_no_duplicates(line)
        except (json.JSONDecodeError, UnicodeDecodeError, ValueError) as error:
            raise RunnerError(71, "evidence_write_failed") from error
        if not isinstance(value, dict) or set(value) != {
            "seq",
            "monotonic_ns",
            "pid_namespace_inode",
            "kind",
            "pid",
            "ppid",
            "state",
        }:
            raise RunnerError(71, "evidence_write_failed")
        nullable_integers = ("pid_namespace_inode", "pid", "ppid")
        state = value["state"]
        if (
            type(value["seq"]) is not int
            or value["seq"] != sequence
            or type(value["monotonic_ns"]) is not int
            or value["monotonic_ns"] < 0
            or value["kind"] not in CONTAINMENT_EVENT_KINDS
            or any(
                value[key] is not None
                and (type(value[key]) is not int or value[key] < 0)
                for key in nullable_integers
            )
            or (
                state is not None
                and (
                    not isinstance(state, str)
                    or len(state) != 1
                    or not state.isascii()
                )
            )
        ):
            raise RunnerError(71, "evidence_write_failed")


def _mount_event(
    sequence: int,
    kind: str,
    *,
    pid_namespace_inode: int | None,
    pid: int | None = None,
    ppid: int | None = None,
    state: str | None = None,
) -> dict[str, object]:
    return {
        "seq": sequence,
        "monotonic_ns": time.monotonic_ns(),
        "pid_namespace_inode": pid_namespace_inode,
        "kind": kind,
        "pid": pid,
        "ppid": ppid,
        "state": state,
    }


def stage_a_main(arguments: Mapping[str, object]) -> int:
    if os.getpid() == 1 or os.getppid() != 1:
        raise RunnerError(68, "namespace_setup_failed")
    if not set_child_subreaper():
        raise RunnerError(68, "subreaper_unverified")
    runner_projection = "/run/substrate-wall/runner.py"
    runner_fd = os.open(
        runner_projection,
        os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW,
    )
    try:
        runner_source = bytearray()
        while True:
            chunk = os.read(runner_fd, 1024 * 1024)
            if not chunk:
                break
            runner_source.extend(chunk)
        parse_stdlib_manifest(bytes(runner_source))
    finally:
        os.close(runner_fd)
    evidence_path = "/run/substrate-wall-evidence"
    evidence_fd, _evidence_identity = open_validated_directory(
        evidence_path,
        expected_uid=os.getuid(),
        expected_mode=0o700,
        validate_ancestors=False,
    )
    stage_a_artifacts = {
        name: _open_existing_artifact_authority(evidence_fd, name)
        for name in STAGED_ARTIFACT_ORDER_V1
    }
    stage_a_provenance_artifact = stage_a_artifacts["provenance.json"]
    stage_a_containment_artifact = stage_a_artifacts["containment.jsonl"]
    provenance = _read_json_from_preopened_artifact(
        evidence_fd,
        stage_a_provenance_artifact,
    )

    def rewrite_provenance() -> None:
        _rewrite_retained_json_artifact(
            evidence_fd,
            stage_a_provenance_artifact,
            provenance,
        )

    def rewrite_containment(data: bytes) -> None:
        validate_containment_jsonl(data)
        _rewrite_retained_artifact(
            evidence_fd,
            stage_a_containment_artifact,
            data,
        )

    if provenance != globals().get("__CANONICAL_STAGE_AUTHORITY"):
        raise RunnerError(68, "invocation_authority_invalid")
    mode = str(arguments["mode"])
    timeout_seconds = int(arguments["timeout_seconds"])
    expected_head = str(arguments["expected_head"])
    root_parent = "/run/substrate-wall/backing"
    (
        root_parent_fd,
        _root_parent_identity,
        tmpfs_mount,
        proc_mount,
    ) = _open_validated_stage_a_root_parent(root_parent)
    uid_map, gid_map = _validate_current_user_namespace_maps("stage-a")
    stage_b_userns_fd = _open_synced_stage_b_user_namespace()
    stage_a_pid_namespace = os.stat("/proc/self/ns/pid").st_ino
    stage_a_mount_namespace = os.stat("/proc/self/ns/mnt").st_ino
    provenance["record_stage"] = "setup"
    provenance["namespace"].update(
        {
            "stage_a_pid_namespace_inode": stage_a_pid_namespace,
            "stage_a_mount_namespace_inode": stage_a_mount_namespace,
            "uid_map": uid_map,
            "gid_map": gid_map,
        }
    )
    provenance["mounts"].update(
        {
            "tmpfs": {
                "source": tmpfs_mount["source"],
                "fstype": tmpfs_mount["fstype"],
                "flags": ",".join(tmpfs_mount["options"]),
                "mount_id": tmpfs_mount["mount_id"],
                "unmounted": False,
            },
            "proc": {
                "source": proc_mount["source"],
                "fstype": proc_mount["fstype"],
                "flags": ",".join(proc_mount["options"]),
                "mount_id": proc_mount["mount_id"],
                "unmounted": False,
            },
            "stage_a": {
                "argv_template_sha256": _template_sha256(
                    BWRAP_STAGE_A_ARGV_TEMPLATE_V1
                ),
                "argv_sha256": arguments["_runtime_argv_sha256"],
                "user_namespace": True,
                "mount_namespace": True,
                "pid_namespace": True,
                "json_status_fd": True,
                "as_pid_1": False,
                "builtin_pid1_fail_safe_only": True,
                "uid_map": uid_map,
                "gid_map": gid_map,
                "private_propagation": True,
                "die_with_parent": True,
                "completed": False,
                "unmounted": False,
            },
        }
    )
    events: list[dict[str, object]] = [
        _mount_event(
            0,
            "stage_a_started",
            pid_namespace_inode=os.stat("/proc/self/ns/pid").st_ino,
            pid=os.getpid(),
            ppid=os.getppid(),
        )
    ]
    root_name = "root"
    os.mkdir(root_name, 0o700, dir_fd=root_parent_fd)
    root_path = os.path.join(root_parent, root_name)
    root_fd, root_identity = open_validated_directory(
        root_path,
        expected_uid=os.getuid(),
        expected_mode=0o700,
        validate_ancestors=False,
    )
    child_paths: dict[str, str] = {}
    child_records = []
    for role, name in (
        ("tmp", "tmp"),
        ("xdg-runtime", "xdg-runtime"),
        ("control", "control"),
        ("target", "target"),
        ("repository-snapshot", "repository-snapshot"),
        ("rustup-home-snapshot", "rustup-home-snapshot"),
        ("cargo-home-seed", "cargo-home-seed"),
        ("cargo-home-runtime", "cargo-home-runtime"),
    ):
        child_paths[role] = os.path.join(root_path, name)
        if role in {
            "repository-snapshot",
            "rustup-home-snapshot",
            "cargo-home-seed",
            "cargo-home-runtime",
        }:
            continue
        os.mkdir(name, 0o700, dir_fd=root_fd)
        child_fd, child_identity = open_validated_directory(
            child_paths[role],
            expected_uid=os.getuid(),
            expected_mode=0o700,
            validate_ancestors=False,
        )
        child_records.append((role, name, child_fd, child_identity))
    _create_canonical_account_projection(root_fd, root_path)
    snapshots = []
    cargo_runtime: dict[str, object] | None = None
    snapshot_records: list[
        tuple[str, str, int, DirectoryIdentity]
    ] = []
    source_records: list[
        tuple[
            int,
            str,
            DirectoryIdentity,
            tuple[str, int, int, int],
        ]
    ] = []
    held: dict[str, HeldExecutable] = {}
    spawned: SpawnedProcess | None = None
    stage_b_launch_attempted = False
    stage_b_reaped = False
    stage_b_pidfd_closed = False
    stage_b_process_teardown_proved = False
    stage_b_namespace_teardown_proved = False
    stage_b_start_time: int | None = None
    stage_b_uid_map: str | None = None
    stage_b_gid_map: str | None = None
    namespace_identities: dict[str, int] | None = None
    stage_b_namespace_reference_baseline: frozenset[
        tuple[str, int]
    ] | None = None
    worker_pidfd: int | None = None
    cargo_log_fd: int | None = None
    cargo_log_identity: tuple[int, int] | None = None
    cargo_log_acl_sha256: str | None = None
    containment_committed = False
    cleanup_deadline: float | None = None
    cleanup_timer_armed = False
    cleanup_previous_handler: object | None = None

    def persist_snapshot_setup() -> None:
        provenance["mounts"]["snapshots"] = snapshots
        provenance["mounts"]["cargo_home_runtime"] = cargo_runtime
        rewrite_provenance()

    def mark_stage_b_reaped() -> None:
        nonlocal stage_b_reaped
        stage_b_reaped = True

    def mark_containment_teardown_proved() -> None:
        nonlocal stage_b_process_teardown_proved
        nonlocal stage_b_namespace_teardown_proved
        if spawned is None or stage_b_namespace_reference_baseline is None:
            raise RunnerError(72, "internal_invariant_failed")
        _verify_spawned_namespace_boundary_teardown(
            spawned,
            stage_b_namespace_reference_baseline,
        )
        stage_b_process_teardown_proved = True
        stage_b_namespace_teardown_proved = True

    def cancel_cleanup_deadline() -> None:
        nonlocal cleanup_timer_armed
        if not cleanup_timer_armed:
            return
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, cleanup_previous_handler)
        cleanup_timer_armed = False

    def arm_cleanup_deadline() -> None:
        nonlocal cleanup_deadline, cleanup_previous_handler
        nonlocal cleanup_timer_armed
        if cleanup_timer_armed or signal.getitimer(signal.ITIMER_REAL) != (0.0, 0.0):
            raise RunnerError(72, "internal_invariant_failed")
        cleanup_deadline = time.monotonic() + CLEANUP_TIMEOUT_SECONDS

        def cleanup_expired(_received: int, _frame: object) -> None:
            raise RunnerError(70, "cleanup_failed")

        cleanup_previous_handler = signal.signal(
            signal.SIGALRM,
            cleanup_expired,
        )
        signal.setitimer(signal.ITIMER_REAL, CLEANUP_TIMEOUT_SECONDS)
        cleanup_timer_armed = True

    try:
        held = validate_platform_startup_tcb()
        snapshot_deadline = time.monotonic() + SNAPSHOT_TIMEOUT_SECONDS
        for source_path in (
            "/run/substrate-wall/source/repository",
            "/run/substrate-wall/source/rustup",
            "/run/substrate-wall/source/cargo",
        ):
            source_mode = stat.S_IMODE(os.stat(source_path).st_mode)
            source_descriptor, source_identity = open_validated_directory(
                source_path,
                expected_uid=os.getuid(),
                expected_mode=source_mode,
                validate_ancestors=False,
            )
            source_records.append(
                (
                    source_descriptor,
                    source_path,
                    source_identity,
                    _manifest_tree(
                        source_descriptor,
                        deadline=snapshot_deadline,
                    ),
                )
            )
        repository_source = "/run/substrate-wall/source/repository"
        stage_a_gitdir_fd = _open_validated_gitdir(repository_source)
        try:
            _verify_clean_repository_with_gitdir(
                repository_source,
                expected_head,
                held["/usr/bin/git"],
                stage_a_gitdir_fd,
            )
            snapshots.append(
                construct_repository_snapshot(
                    repository_source,
                    expected_head,
                    held["/usr/bin/git"],
                    child_paths["repository-snapshot"],
                    deadline=snapshot_deadline,
                    gitdir_fd=stage_a_gitdir_fd,
                )
            )
            persist_snapshot_setup()
        finally:
            os.close(stage_a_gitdir_fd)
        repository_fd, repository_identity = open_validated_directory(
            child_paths["repository-snapshot"],
            expected_uid=os.getuid(),
            expected_mode=0o700,
            validate_ancestors=False,
        )
        snapshot_records.append(
            (
                "repository-snapshot",
                "repository-snapshot",
                repository_fd,
                repository_identity,
            )
        )
        snapshots.append(
            construct_rustup_home_snapshot(
                "/run/substrate-wall/source/rustup",
                child_paths["rustup-home-snapshot"],
                deadline=snapshot_deadline,
            )
        )
        persist_snapshot_setup()
        rustup_fd, rustup_identity = open_validated_directory(
            child_paths["rustup-home-snapshot"],
            expected_uid=os.getuid(),
            expected_mode=0o700,
            validate_ancestors=False,
        )
        snapshot_records.append(
            (
                "rustup-home-snapshot",
                "rustup-home-snapshot",
                rustup_fd,
                rustup_identity,
            )
        )
        snapshots.append(
            construct_cargo_home_seed(
                "/run/substrate-wall/source/cargo",
                child_paths["repository-snapshot"],
                child_paths["cargo-home-seed"],
                deadline=snapshot_deadline,
            )
        )
        persist_snapshot_setup()
        seed_fd, seed_identity = open_validated_directory(
            child_paths["cargo-home-seed"],
            expected_uid=os.getuid(),
            expected_mode=0o700,
            validate_ancestors=False,
        )
        snapshot_records.append(
            (
                "cargo-home-seed",
                "cargo-home-seed",
                seed_fd,
                seed_identity,
            )
        )
        cargo_runtime = construct_cargo_home_runtime(
            child_paths["cargo-home-seed"],
            child_paths["cargo-home-runtime"],
            deadline=snapshot_deadline,
        )
        persist_snapshot_setup()
        runtime_fd, runtime_identity = open_validated_directory(
            child_paths["cargo-home-runtime"],
            expected_uid=os.getuid(),
            expected_mode=0o700,
            validate_ancestors=False,
        )
        snapshot_records.append(
            (
                "cargo-home-runtime",
                "cargo-home-runtime",
                runtime_fd,
                runtime_identity,
            )
        )
        seal_snapshot_mounts(
            (
                child_paths["repository-snapshot"],
                child_paths["rustup-home-snapshot"],
                child_paths["cargo-home-seed"],
                child_paths["cargo-home-runtime"],
            )
        )
        os.fchmod(runtime_fd, 0o700)
        _check_snapshot_deadline(snapshot_deadline)
        sealed_seed_manifest = _manifest_tree(
            child_paths["cargo-home-seed"],
            deadline=snapshot_deadline,
        )[0]
        sealed_runtime_manifest = _manifest_tree(
            child_paths["cargo-home-runtime"],
            deadline=snapshot_deadline,
        )[0]
        if sealed_runtime_manifest != sealed_seed_manifest:
            raise RunnerError(67, "snapshot_identity_invalid")
        cargo_runtime["seed_manifest_sha256"] = sealed_seed_manifest
        cargo_runtime["pre_manifest_sha256"] = sealed_runtime_manifest
        sealed_records = []
        for role, name, child_fd, initial_identity in snapshot_records:
            sealed_identity = _directory_identity(child_fd, child_paths[role])
            expected_mode = 0o700 if role == "cargo-home-runtime" else 0o500
            if (
                (sealed_identity.dev, sealed_identity.ino)
                != (initial_identity.dev, initial_identity.ino)
                or sealed_identity.mode != expected_mode
                or not sealed_identity.path_matches_fd
            ):
                raise RunnerError(67, "snapshot_identity_invalid")
            sealed_records.append((role, name, child_fd, sealed_identity))
        snapshot_records = sealed_records
        snapshot_path_by_role = {
            "repository": child_paths["repository-snapshot"],
            "rustup-home": child_paths["rustup-home-snapshot"],
            "cargo-home-seed": child_paths["cargo-home-seed"],
        }
        for snapshot in snapshots:
            snapshot["snapshot_manifest_sha256"] = _manifest_tree(
                snapshot_path_by_role[str(snapshot["role"])],
                deadline=snapshot_deadline,
            )[0]
        directory_authority = {
            role: (descriptor, identity)
            for role, _name, descriptor, identity in (
                child_records + snapshot_records
            )
        }
        projection_sources = {
            "repository-snapshot": directory_authority[
                "repository-snapshot"
            ][1],
            "rustup-home-snapshot": directory_authority[
                "rustup-home-snapshot"
            ][1],
            "cargo-home-runtime": directory_authority[
                "cargo-home-runtime"
            ][1],
            "target": directory_authority["target"][1],
            "tmp": directory_authority["tmp"][1],
            "xdg-runtime": directory_authority["xdg-runtime"][1],
            "control": directory_authority["control"][1],
        }
        stage_b_authority = {
            "schema": "substrate.canonical_shell_wall_stage_authority.v1",
            "invocation_id": provenance["invocation_id"],
            "runner_sha256": inline_sha256(bytes(runner_source)),
            "expected_head": expected_head,
            "mode": mode,
            "label": arguments["label"],
            "timeout_seconds": timeout_seconds,
            "projections": {
                role: {
                    "dev": identity.dev,
                    "ino": identity.ino,
                    "mode": identity.mode,
                    "uid": identity.uid,
                    "writable": writable,
                }
                for role, identity in projection_sources.items()
                for writable in (
                    role
                    in {
                        "cargo-home-runtime",
                        "target",
                        "tmp",
                        "xdg-runtime",
                        "control",
                    },
                )
            },
        }
        stage_b_authority_bytes = (
            json.dumps(
                stage_b_authority,
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=True,
            )
            + "\n"
        ).encode("ascii")
        _write_file_at(
            int(directory_authority["control"][0]),
            "authority.json",
            stage_b_authority_bytes,
            mode=0o400,
        )
        provenance["record_stage"] = "setup"
        provenance["request"]["tmpdir"] = child_paths["tmp"]
        provenance["request"]["xdg_runtime_dir"] = STAGE_B_XDG_RUNTIME_DIR
        provenance["request"]["target_dir"] = child_paths["target"]
        provenance["mounts"]["snapshots"] = snapshots
        provenance["mounts"]["cargo_home_runtime"] = cargo_runtime
        rewrite_provenance()
        setup_deadline = time.monotonic() + SETUP_TIMEOUT_SECONDS
        control_path = os.path.join(child_paths["control"], "worker.sock")
        control_directory_fd = int(directory_authority["control"][0])
        listener = create_worker_control_listener(control_path)
        control_socket_details = os.stat(
            "worker.sock",
            dir_fd=control_directory_fd,
            follow_symlinks=False,
        )
        control_socket_identity = (
            control_socket_details.st_dev,
            control_socket_details.st_ino,
        )
        output_read, output_write = os.pipe2(os.O_CLOEXEC)
        output_details = os.fstat(output_read)
        cargo_log_fd = int(stage_a_artifacts["cargo.log"]["fd"])
        environment = _canonical_wall_environment(os.environ, root_path)
        stage_b_launch_attempted = True
        stage_b_namespace_reference_baseline = _namespace_reference_census()
        spawned, status_fd, stage_b_argv = launch_stage_b_bwrap(
            bwrap=held["/usr/bin/bwrap"],
            userns_fd=stage_b_userns_fd,
            source=bytes(runner_source),
            root=child_paths["target"],
            repository_snapshot=child_paths["repository-snapshot"],
            rustup_snapshot=child_paths["rustup-home-snapshot"],
            cargo_runtime=child_paths["cargo-home-runtime"],
            control_directory=child_paths["control"],
            repository_cwd=REPOSITORY_CANONICAL_PATH,
            mode=mode,
            label=str(arguments["label"]),
            timeout_seconds=timeout_seconds,
            expected_head=expected_head,
            environment=environment,
            output_write_fd=output_write,
        )
        provenance["request"]["launcher"][
            "stage_b_argv_sha256"
        ] = inline_sha256(_nul_frame(stage_b_argv))
        provenance["namespace"].update(
            {
                "stage_b_bwrap_pid": spawned.pid,
                "stage_b_bwrap_pidfd_opened": True,
            }
        )
        rewrite_provenance()
        stage_b_start_time = _process_start_time_ticks(spawned.pid)
        provenance["namespace"][
            "stage_b_bwrap_start_time_ticks"
        ] = stage_b_start_time
        rewrite_provenance()
        os.close(output_write)
        try:
            first_status_line = _read_stage_b_first_status_or_teardown(
                status_fd,
                spawned,
                deadline=setup_deadline,
                mark_stage_b_reaped=mark_stage_b_reaped,
                mark_containment_teardown_proved=(
                    mark_containment_teardown_proved
                ),
            )
            first_status = _parse_first_bwrap_record(first_status_line)
            provenance["namespace"]["stage_b_status_received"] = True
            rewrite_provenance()
            (
                worker_pid,
                namespace_identities,
                worker_start_time,
                worker_pidfd,
            ) = _capture_stage_b_worker_identity(first_status)
            stage_b_uid_map, stage_b_gid_map = _read_user_namespace_maps(
                worker_pid
            )
            if (
                stage_b_uid_map != CANONICAL_STAGE_B_UID_MAP
                or stage_b_gid_map != CANONICAL_STAGE_B_GID_MAP
            ):
                raise RunnerError(68, "namespace_setup_failed")
            provenance["namespace"].update(
                {
                    "worker_stage_a_pid": worker_pid,
                    "worker_start_time_ticks": worker_start_time,
                    "stage_b_pid_namespace_inode": namespace_identities[
                        "pid-namespace"
                    ],
                    "stage_b_mount_namespace_inode": namespace_identities[
                        "mnt-namespace"
                    ],
                    "worker_pidfd_opened": True,
                }
            )
            rewrite_provenance()
            endpoint = accept_authenticated_worker(
                listener,
                expected_pid=worker_pid,
                deadline=setup_deadline,
            )
            _require_pidfds_live(spawned.pidfd, worker_pidfd)
            listener.close()
            remove_control_socket_at(
                control_directory_fd,
                "worker.sock",
                control_socket_identity,
            )
            endpoint.settimeout(
                max(0.001, setup_deadline - time.monotonic())
            )
            try:
                endpoint.sendall(START_RECORD)
            except (TimeoutError, socket.timeout) as error:
                raise RunnerError(68, "worker_handshake_failed") from error
            endpoint.settimeout(None)
        except RunnerError as error:
            try:
                if error.reason == "premature_stage_b_exit":
                    provenance["containment"][
                        "premature_stage_b_exit"
                    ] = True
                elif error.reason == "stage_b_setup_timeout":
                    provenance["containment"][
                        "stage_b_setup_timed_out"
                    ] = True
                if spawned is not None and not stage_b_reaped:
                    _terminate_exact_spawned_process(spawned)
                    mark_stage_b_reaped()
                if stage_b_launch_attempted and not stage_b_process_teardown_proved:
                    _reap_owned_children_to_echild(
                        time.monotonic() + CLEANUP_TIMEOUT_SECONDS
                    )
                    mark_containment_teardown_proved()
                if stage_b_reaped:
                    provenance["namespace"]["stage_b_exit_received"] = True
                _preserve_pre_ready_stage_b_output(
                    output_read,
                    cargo_log_fd,
                    deadline=time.monotonic() + CLEANUP_TIMEOUT_SECONDS,
                    output_pipe_identity=(
                        output_details.st_dev,
                        output_details.st_ino,
                    ),
                    provenance=provenance,
                )
                rewrite_provenance()
            except RunnerError:
                pass
            raise
        provenance["record_stage"] = "setup"
        provenance["request"]["launcher"][
            "stage_b_argv_sha256"
        ] = inline_sha256(_nul_frame(stage_b_argv))
        provenance["mounts"]["stage_b"] = {
            "argv_template_sha256": _template_sha256(
                BWRAP_STAGE_B_ARGV_TEMPLATE_V1
            ),
            "argv_sha256": inline_sha256(_nul_frame(stage_b_argv)),
            "user_namespace": True,
            "mount_namespace": True,
            "pid_namespace": True,
            "json_status_fd": True,
            "as_pid_1": True,
            "builtin_pid1_fail_safe_only": False,
            "uid_map": stage_b_uid_map,
            "gid_map": stage_b_gid_map,
            "private_propagation": True,
            "die_with_parent": True,
            "completed": False,
            "unmounted": False,
        }
        provenance["namespace"].update(
            {
                "stage_b_bwrap_pid": spawned.pid,
                "worker_stage_a_pid": worker_pid,
                "stage_b_bwrap_start_time_ticks": stage_b_start_time,
                "worker_start_time_ticks": worker_start_time,
                "stage_b_pid_namespace_inode": namespace_identities[
                    "pid-namespace"
                ],
                "stage_b_mount_namespace_inode": namespace_identities[
                    "mnt-namespace"
                ],
                "stage_b_bwrap_pidfd_opened": True,
                "stage_b_status_received": True,
                "worker_pidfd_opened": True,
                "worker_peer_credentials_verified": True,
                "worker_ready_received": True,
                "control_path_absence_proved": True,
                "worker_start_sent": True,
                "worker_subreaper_verified": True,
            }
        )
        rewrite_provenance()

        def persist_authenticated_worker_result(
            authenticated: dict[str, object],
        ) -> None:
            nonlocal containment_committed
            if (
                int(authenticated["pid_namespace_inode"])
                != namespace_identities["pid-namespace"]
            ):
                raise RunnerError(68, "control_channel_invalid")
            events.extend(
                (
                    _mount_event(
                        len(events),
                        (
                            "echild_observed"
                            if authenticated["echld_observed"]
                            else "teardown_started"
                        ),
                        pid_namespace_inode=int(
                            authenticated["pid_namespace_inode"]
                        ),
                    ),
                    _mount_event(
                        len(events) + 1,
                        (
                            "containment_empty_received"
                            if authenticated["discriminator"]
                            == "CONTAINMENT_EMPTY"
                            else "teardown_finished"
                        ),
                        pid_namespace_inode=int(
                            authenticated["pid_namespace_inode"]
                        ),
                    ),
                )
            )
            staged_containment = b"".join(
                (
                    json.dumps(event, sort_keys=True, separators=(",", ":"))
                    + "\n"
                ).encode("ascii")
                for event in events
            )
            if len(staged_containment) > MAX_CONTAINMENT_BYTES:
                raise RunnerError(71, "evidence_limit_exceeded")
            rewrite_containment(staged_containment)
            provenance["record_stage"] = "containment"
            provenance["containment"].update(
                {
                    "cargo_pid": authenticated["primary_pid"],
                    "cargo_exit": authenticated["primary_status"],
                    "reaped_descendants": authenticated[
                        "reaped_descendants"
                    ],
                    "event_count": len(events),
                    "wall_timed_out": authenticated["timed_out"],
                    "echld_observed": authenticated["echld_observed"],
                    "authenticated_empty_record": (
                        authenticated["discriminator"]
                        == "CONTAINMENT_EMPTY"
                    ),
                    "forced_teardown": authenticated["forced_teardown"],
                    "events_file": "containment.jsonl",
                }
            )
            provenance["namespace"]["worker_echild_received"] = authenticated[
                "echld_observed"
            ]
            rewrite_provenance()
            os.fsync(evidence_fd)
            containment_committed = True

        output, worker_result, final_status, stage_b_exit = (
            supervise_stage_b_channels(
                output_fd=output_read,
                log_fd=cargo_log_fd,
                endpoint=endpoint,
                status_fd=status_fd,
                spawned=spawned,
                worker_pidfd=worker_pidfd,
                first_status_line=first_status_line,
                deadline=(
                    time.monotonic()
                    + timeout_seconds
                    + CLEANUP_TIMEOUT_SECONDS
                    + 15
                ),
                persist_worker_result=persist_authenticated_worker_result,
                mark_stage_b_reaped=mark_stage_b_reaped,
            )
        )
        stage_b_reaped = True
        if (
            _reap_owned_children_to_echild(
                time.monotonic() + CLEANUP_TIMEOUT_SECONDS
            )
            != 0
        ):
            raise RunnerError(68, "stage_b_liveness_failed")
        stage_b_process_teardown_proved = True
        os.close(output_read)
        endpoint.close()
        os.close(status_fd)
        stage_b_success = not (
            worker_result.get("discriminator") != "CONTAINMENT_EMPTY"
            or worker_result.get("echld_observed") is not True
            or worker_result.get("timed_out") is not False
            or worker_result.get("forced_teardown") is not False
            or worker_result.get("survivors") != []
            or worker_result.get("received_signals") != []
            or int(worker_result["pid_namespace_inode"])
            != namespace_identities["pid-namespace"]
            or final_status["exit-code"] != 0
            or stage_b_exit != 0
        )
        if worker_result.get("received_signals") != []:
            stage_b_failure_reason = "stage_b_liveness_failed"
        elif worker_result.get("survivors") != []:
            stage_b_failure_reason = "surviving_descendant"
        elif worker_result.get("timed_out") is True:
            stage_b_failure_reason = "containment_timeout"
        elif not stage_b_success:
            stage_b_failure_reason = "stage_b_liveness_failed"
        else:
            stage_b_failure_reason = None
        events.extend(
            (
                _mount_event(
                    len(events),
                    "stage_b_exited",
                    pid_namespace_inode=int(
                        worker_result["pid_namespace_inode"]
                    ),
                    pid=spawned.pid,
                ),
                _mount_event(
                    len(events) + 1,
                    "output_pipe_eof",
                    pid_namespace_inode=int(
                        worker_result["pid_namespace_inode"]
                    ),
                ),
            )
        )
        containment_bytes = b"".join(
            (
                json.dumps(event, sort_keys=True, separators=(",", ":"))
                + "\n"
            ).encode("ascii")
            for event in events
        )
        rewrite_containment(containment_bytes)
        containment_committed = True
        primary_status_value = worker_result["primary_status"]
        cargo_exit = (
            int(primary_status_value)
            if type(primary_status_value) is int
            else None
        )
        provenance["record_stage"] = "containment"
        provenance["request"]["launcher"][
            "stage_b_argv_sha256"
        ] = inline_sha256(_nul_frame(stage_b_argv))
        provenance["mounts"]["stage_b"] = {
            "argv_template_sha256": _template_sha256(
                BWRAP_STAGE_B_ARGV_TEMPLATE_V1
            ),
            "argv_sha256": inline_sha256(_nul_frame(stage_b_argv)),
            "user_namespace": True,
            "mount_namespace": True,
            "pid_namespace": True,
            "json_status_fd": True,
            "as_pid_1": True,
            "builtin_pid1_fail_safe_only": False,
            "uid_map": stage_b_uid_map,
            "gid_map": stage_b_gid_map,
            "private_propagation": True,
            "die_with_parent": True,
            "completed": True,
            "unmounted": False,
        }
        provenance["mounts"]["snapshots"] = snapshots
        provenance["mounts"]["cargo_home_runtime"] = cargo_runtime
        provenance["containment"].update(
            {
                "cargo_pid": worker_result["primary_pid"],
                "cargo_exit": cargo_exit,
                "stage_b_exit": stage_b_exit,
                "reaped_descendants": worker_result[
                    "reaped_descendants"
                ],
                "event_count": len(events),
                "output_pipe_dev": output_details.st_dev,
                "output_pipe_ino": output_details.st_ino,
                "output_bytes_preserved": output["preserved_bytes"],
                "wall_timed_out": worker_result["timed_out"],
                "echld_observed": worker_result["echld_observed"],
                "authenticated_empty_record": (
                    worker_result["discriminator"] == "CONTAINMENT_EMPTY"
                ),
                "forced_teardown": worker_result["forced_teardown"],
                "output_pipe_opened_before_stage_b": True,
                "single_pipe_for_stdout_stderr": True,
                "output_eof_after_stage_b_reap": output[
                    "eof_finalized_after_stage_b_reap"
                ],
                "output_overflow": output["overflow"],
                "events_file": "containment.jsonl",
            }
        )
        provenance["namespace"].update(
            {
                "stage_b_bwrap_pid": spawned.pid,
                "worker_stage_a_pid": worker_pid,
                "stage_b_bwrap_start_time_ticks": stage_b_start_time,
                "worker_start_time_ticks": worker_start_time,
                "stage_b_pid_namespace_inode": namespace_identities[
                    "pid-namespace"
                ],
                "stage_b_mount_namespace_inode": namespace_identities[
                    "mnt-namespace"
                ],
                "stage_b_bwrap_pidfd_opened": True,
                "stage_b_status_received": True,
                "worker_pidfd_opened": True,
                "worker_peer_credentials_verified": True,
                "worker_ready_received": True,
                "control_path_absence_proved": True,
                "worker_start_sent": True,
                "worker_subreaper_verified": True,
                "worker_echild_received": worker_result[
                    "echld_observed"
                ],
                "stage_b_exit_received": True,
            }
        )
        if stage_b_failure_reason is not None:
            _record_ineligibility(
                provenance,
                stage_b_failure_reason,
                68,
            )
        rewrite_provenance()
        if not verify_namespace_mount_teardown(
            spawned.pid,
            spawned.pidfd,
            expected_start_time=stage_b_start_time,
            expected_namespace_inodes={
                "mnt": namespace_identities["mnt-namespace"],
                "pid": namespace_identities["pid-namespace"],
            },
        ):
            raise RunnerError(70, "mount_teardown_failed")
        if stage_b_namespace_reference_baseline is None:
            raise RunnerError(72, "internal_invariant_failed")
        _verify_spawned_namespace_boundary_teardown(
            spawned,
            stage_b_namespace_reference_baseline,
        )
        stage_b_namespace_teardown_proved = True
        provenance["mounts"]["stage_b"]["unmounted"] = True
        rewrite_provenance()
        os.close(spawned.pidfd)
        stage_b_pidfd_closed = True
        os.close(worker_pidfd)
        worker_pidfd = None
        arm_cleanup_deadline()
        if stage_b_failure_reason is not None:
            raise RunnerError(68, stage_b_failure_reason)
        if output["overflow"]:
            if cargo_log_fd is None:
                raise RunnerError(72, "internal_invariant_failed")
            os.fsync(cargo_log_fd)
            diagnostic_prefix = output["diagnostic_prefix"]
            if (
                not isinstance(diagnostic_prefix, bytes)
                or int(output["preserved_bytes"]) != len(diagnostic_prefix)
                or len(diagnostic_prefix) > MAX_DIAGNOSTIC_PREFIX
            ):
                raise RunnerError(72, "internal_invariant_failed")
            cargo_overflow_record = _revalidate_preopened_artifact(
                evidence_fd,
                stage_a_artifacts["cargo.log"],
            )
            if (
                int(cargo_overflow_record["bytes"])
                != len(diagnostic_prefix)
                or str(cargo_overflow_record["sha256"])
                != inline_sha256(diagnostic_prefix)
            ):
                raise RunnerError(71, "output_capture_failed")
            _record_ineligibility(
                provenance,
                "evidence_limit_exceeded",
                71,
            )
            rewrite_provenance()
            raise RunnerError(71, "evidence_limit_exceeded")
        if cargo_log_fd is None or not isinstance(output["sha256"], str):
            raise RunnerError(72, "internal_invariant_failed")
        if cargo_exit is None:
            raise RunnerError(72, "internal_invariant_failed")
        os.fsync(cargo_log_fd)
        cargo_log_details = os.fstat(cargo_log_fd)
        cargo_log_named = os.stat(
            "cargo.log",
            dir_fd=evidence_fd,
            follow_symlinks=False,
        )
        cargo_log_acl_sha256, cargo_log_foreign_write = read_effective_acl(
            cargo_log_fd
        )
        cargo_log_identity = (
            cargo_log_details.st_dev,
            cargo_log_details.st_ino,
        )
        if (
            not stat.S_ISREG(cargo_log_details.st_mode)
            or cargo_log_details.st_uid != os.getuid()
            or stat.S_IMODE(cargo_log_details.st_mode) != 0o600
            or cargo_log_details.st_nlink != 1
            or cargo_log_foreign_write
            or (
                cargo_log_named.st_dev,
                cargo_log_named.st_ino,
            )
            != cargo_log_identity
            or cargo_log_details.st_size != int(output["bytes"])
            or hash_open_file(cargo_log_fd) != output["sha256"]
        ):
            raise RunnerError(71, "output_capture_failed")
        log_parts = bytearray()
        cargo_log_offset = 0
        while True:
            chunk = os.pread(
                cargo_log_fd,
                1024 * 1024,
                cargo_log_offset,
            )
            if not chunk:
                break
            log_parts.extend(chunk)
            cargo_log_offset += len(chunk)
        summary, failure_names, signatures = summarize_test_log(
            bytes(log_parts),
            cargo_exit,
        )
        if failure_names is not None:
            _rewrite_retained_artifact(
                evidence_fd,
                stage_a_artifacts["failure-names.txt"],
                failure_names,
            )
            _rewrite_retained_artifact(
                evidence_fd,
                stage_a_artifacts["normalized-signatures.txt"],
                signatures or b"",
            )
        summary_bytes = (
            json.dumps(summary, sort_keys=True, separators=(",", ":")) + "\n"
        ).encode("ascii")
        _rewrite_retained_artifact(
            evidence_fd,
            stage_a_artifacts["summary.json"],
            summary_bytes,
        )
        runtime_validation = validate_cargo_home_runtime_writes(
            child_paths["cargo-home-seed"],
            child_paths["cargo-home-runtime"],
        )
        cargo_runtime.update(runtime_validation)
        for (
            source_descriptor,
            source_path,
            source_identity,
            source_manifest,
        ) in source_records:
            if (
                _directory_identity(source_descriptor, source_path)
                != source_identity
                or _manifest_tree(source_descriptor) != source_manifest
            ):
                raise RunnerError(70, "snapshot_identity_invalid")
        for snapshot in snapshots:
            post_manifest = _manifest_tree(
                snapshot_path_by_role[str(snapshot["role"])]
            )[0]
            snapshot["post_manifest_equal"] = (
                post_manifest == snapshot["snapshot_manifest_sha256"]
            )
            if snapshot["post_manifest_equal"] is not True:
                raise RunnerError(70, "snapshot_identity_invalid")
        if (
            cargo_log_fd is None
            or cargo_log_identity is None
            or cargo_log_acl_sha256 is None
        ):
            raise RunnerError(72, "internal_invariant_failed")
        cargo_log_post = os.fstat(cargo_log_fd)
        cargo_log_named_post = os.stat(
            "cargo.log",
            dir_fd=evidence_fd,
            follow_symlinks=False,
        )
        cargo_log_acl_post, cargo_log_foreign_write_post = read_effective_acl(
            cargo_log_fd
        )
        if (
            (cargo_log_post.st_dev, cargo_log_post.st_ino)
            != cargo_log_identity
            or (
                cargo_log_named_post.st_dev,
                cargo_log_named_post.st_ino,
            )
            != cargo_log_identity
            or cargo_log_post.st_size != int(output["bytes"])
            or cargo_log_acl_post != cargo_log_acl_sha256
            or cargo_log_foreign_write_post
            or hash_open_file(cargo_log_fd) != output["sha256"]
        ):
            raise RunnerError(71, "output_capture_failed")
        provenance["result"] = summary
        rewrite_provenance()
        root_evidence: dict[str, dict[str, object]] = {}
        cleanup_records = {
            role: (name, child_fd, child_identity)
            for role, name, child_fd, child_identity in (
                child_records + snapshot_records
            )
        }
        if set(cleanup_records) != set(STAGE_A_CLEANUP_ROLE_ORDER_V1[:-1]):
            raise RunnerError(72, "internal_invariant_failed")
        cleanup_preflight: dict[str, DirectoryIdentity] = {}
        for role in STAGE_A_CLEANUP_ROLE_ORDER_V1[:-1]:
            _name, child_fd, child_identity = cleanup_records[role]
            child_post = _directory_identity(child_fd, child_paths[role])
            if child_post != child_identity:
                raise RunnerError(70, "cleanup_identity_mismatch")
            cleanup_preflight[role] = child_post
        root_precleanup = _directory_identity(root_fd, root_path)
        if root_precleanup != root_identity:
            raise RunnerError(70, "cleanup_identity_mismatch")
        _validate_tree_for_cleanup(
            root_fd,
            root_precleanup.mount_id,
        )
        cleanup_authority = _mint_cleanup_quiescence(
            "stage-a",
            lifecycle_proof={
                "echld_observed": worker_result.get("echld_observed") is True,
                "stage_b_reaped": stage_b_reaped,
                "stage_b_process_teardown_proved": stage_b_process_teardown_proved,
                "stage_b_namespace_teardown_proved": stage_b_namespace_teardown_proved,
            },
        )
        for role in STAGE_A_CLEANUP_ROLE_ORDER_V1[:-1]:
            name, child_fd, child_identity = cleanup_records[role]
            child_post = cleanup_preflight[role]
            proof = remove_tree_at(
                root_fd,
                name,
                expected=child_post,
                cleanup_authority=cleanup_authority,
            )
            os.close(child_fd)
            root_evidence[role] = {
                "role": role,
                "path": child_paths[role],
                "pre": child_identity.as_dict(),
                "post": child_post.as_dict(),
                **proof,
            }
            snapshot_role = {
                "repository-snapshot": "repository",
                "rustup-home-snapshot": "rustup-home",
                "cargo-home-seed": "cargo-home-seed",
            }.get(role)
            if snapshot_role is not None:
                matching = [
                    snapshot
                    for snapshot in snapshots
                    if snapshot["role"] == snapshot_role
                ]
                if len(matching) != 1:
                    raise RunnerError(72, "internal_invariant_failed")
                matching[0]["removed"] = True
            elif role == "cargo-home-runtime":
                cargo_runtime["removed"] = True
        root_post = _directory_identity(root_fd, root_path)
        root_proof = remove_tree_at(
            root_parent_fd,
            root_name,
            expected=root_post,
            cleanup_authority=cleanup_authority,
        )
        os.close(root_fd)
        root_evidence["root"] = {
            "role": "root",
            "path": root_path,
            "pre": root_identity.as_dict(),
            "post": root_post.as_dict(),
            **root_proof,
        }
        provenance["roots"] = [
            root_evidence[role]
            for role in (
                "root",
                "tmp",
                "xdg-runtime",
                "control",
                "target",
                "repository-snapshot",
                "rustup-home-snapshot",
                "cargo-home-seed",
                "cargo-home-runtime",
            )
        ]
        provenance["record_stage"] = "cleanup"
        provenance["runner_exit_code"] = 69
        rewrite_provenance()
        if cleanup_deadline is None or time.monotonic() >= cleanup_deadline:
            raise RunnerError(70, "cleanup_failed")
        cancel_cleanup_deadline()
        return 0
    except RunnerError as error:
        cancel_cleanup_deadline()
        if not containment_committed and events:
            try:
                containment_bytes = b"".join(
                    (
                        json.dumps(
                            event,
                            sort_keys=True,
                            separators=(",", ":"),
                        )
                        + "\n"
                    ).encode("ascii")
                    for event in events
                )
                if len(containment_bytes) > MAX_CONTAINMENT_BYTES:
                    raise RunnerError(71, "evidence_limit_exceeded")
                rewrite_containment(containment_bytes)
                containment_committed = True
                provenance["containment"]["event_count"] = len(events)
                provenance["containment"]["events_file"] = "containment.jsonl"
            except RunnerError:
                pass
        _record_ineligibility(provenance, error.reason, error.exit_code)
        try:
            rewrite_provenance()
        except RunnerError:
            pass
        raise
    finally:
        cancel_cleanup_deadline()
        if spawned is not None and not stage_b_reaped:
            _terminate_exact_spawned_process(spawned)
            stage_b_reaped = True
        if stage_b_launch_attempted and not stage_b_process_teardown_proved:
            try:
                _reap_owned_children_to_echild(
                    time.monotonic() + CLEANUP_TIMEOUT_SECONDS
                )
            except RunnerError:
                _record_ineligibility(
                    provenance,
                    "mount_teardown_failed",
                    70,
                )
                try:
                    rewrite_provenance()
                except RunnerError:
                    pass
            else:
                stage_b_process_teardown_proved = True
        if (
            spawned is not None
            and not stage_b_pidfd_closed
            and not stage_b_namespace_teardown_proved
            and stage_b_start_time is not None
            and namespace_identities is not None
        ):
            try:
                verify_namespace_mount_teardown(
                    spawned.pid,
                    spawned.pidfd,
                    expected_start_time=stage_b_start_time,
                    expected_namespace_inodes={
                        "mnt": namespace_identities["mnt-namespace"],
                        "pid": namespace_identities["pid-namespace"],
                    },
                )
                if stage_b_namespace_reference_baseline is None:
                    raise RunnerError(72, "internal_invariant_failed")
                _verify_spawned_namespace_boundary_teardown(
                    spawned,
                    stage_b_namespace_reference_baseline,
                )
            except RunnerError:
                _record_ineligibility(
                    provenance,
                    "mount_teardown_failed",
                    70,
                )
                stage_b_mount = provenance["mounts"].get("stage_b")
                if isinstance(stage_b_mount, dict):
                    stage_b_mount["unmounted"] = False
                try:
                    rewrite_provenance()
                except RunnerError:
                    pass
            else:
                stage_b_namespace_teardown_proved = True
                stage_b_mount = provenance["mounts"].get("stage_b")
                if isinstance(stage_b_mount, dict):
                    stage_b_mount["unmounted"] = True
                provenance["namespace"]["stage_b_exit_received"] = (
                    stage_b_reaped
                )
                try:
                    rewrite_provenance()
                except RunnerError:
                    pass
        if (
            stage_b_launch_attempted
            and spawned is not None
            and not stage_b_namespace_teardown_proved
            and (
                stage_b_start_time is None
                or namespace_identities is None
            )
        ):
            _record_ineligibility(
                provenance,
                "mount_teardown_failed",
                70,
            )
            try:
                rewrite_provenance()
            except RunnerError:
                pass
        if spawned is not None and not stage_b_pidfd_closed:
            try:
                os.close(spawned.pidfd)
            except OSError:
                pass
        if worker_pidfd is not None:
            try:
                os.close(worker_pidfd)
            except OSError:
                pass
        for executable in held.values():
            try:
                os.close(executable.fd)
            except OSError:
                pass
        for descriptor, _path, _identity, _manifest in source_records:
            try:
                os.close(descriptor)
            except OSError:
                pass
        for _role, _name, descriptor, _identity in (
            child_records + snapshot_records
        ):
            try:
                os.close(descriptor)
            except OSError:
                pass
        for artifact in stage_a_artifacts.values():
            try:
                os.close(int(artifact["fd"]))
            except OSError:
                pass
        for descriptor in (
            stage_b_userns_fd,
            root_fd,
            root_parent_fd,
            evidence_fd,
        ):
            try:
                os.close(descriptor)
            except OSError:
                pass


def _executable_identity(executable: HeldExecutable) -> dict[str, object]:
    details = os.fstat(executable.fd)
    opened_path = executable.path
    named = os.stat(opened_path, follow_symlinks=False)
    if stat.S_ISLNK(named.st_mode):
        opened_path = os.path.join(
            os.path.dirname(executable.path),
            os.readlink(executable.path),
        )
        named = os.stat(opened_path, follow_symlinks=False)
    _acl_sha256, foreign_write = read_effective_acl(executable.fd)
    if (
        not stat.S_ISREG(details.st_mode)
        or (details.st_dev, details.st_ino) != (named.st_dev, named.st_ino)
        or details.st_uid != executable.identity[2]
        or stat.S_IMODE(details.st_mode) != executable.identity[3]
        or details.st_nlink != 1
        or foreign_write
        or hash_open_file(executable.fd) != executable.sha256
    ):
        raise RunnerError(65, "executable_identity_drift")
    return {
        "dev": details.st_dev,
        "ino": details.st_ino,
        "uid": details.st_uid,
        "mode": stat.S_IMODE(details.st_mode),
        "kind": "regular",
        "sha256": executable.sha256,
        "path_matches_fd": True,
        "owner_ancestor_acl_safe": True,
        "executable": bool(details.st_mode & 0o111),
    }


def _held_regular_file(
    path: str,
    expected_sha256: str,
) -> tuple[int, dict[str, object]]:
    validate_safe_ancestor_chain(
        path,
        expected_uid=os.getuid(),
        include_leaf=False,
    )
    fd = os.open(path, os.O_RDONLY | os.O_CLOEXEC | os.O_NOFOLLOW)
    try:
        details = os.fstat(fd)
        named = os.stat(path, follow_symlinks=False)
        _acl_sha256, foreign_write = read_effective_acl(fd)
        if (
            not stat.S_ISREG(details.st_mode)
            or details.st_uid != os.getuid()
            or details.st_nlink != 1
            or foreign_write
            or (details.st_dev, details.st_ino)
            != (named.st_dev, named.st_ino)
            or hash_open_file(fd) != expected_sha256
        ):
            raise RunnerError(65, "executable_identity_invalid")
        return fd, {
            "dev": details.st_dev,
            "ino": details.st_ino,
            "uid": details.st_uid,
            "mode": stat.S_IMODE(details.st_mode),
            "kind": "regular",
            "sha256": expected_sha256,
            "path_matches_fd": True,
            "owner_ancestor_acl_safe": True,
        }
    except BaseException:
        os.close(fd)
        raise


def _held_symlink(path: str) -> dict[str, object]:
    validate_safe_ancestor_chain(
        path,
        expected_uid=os.getuid(),
        include_leaf=False,
    )
    details = os.stat(path, follow_symlinks=False)
    if (
        not stat.S_ISLNK(details.st_mode)
        or details.st_uid != os.getuid()
        or os.readlink(path) != "rustup"
    ):
        raise RunnerError(65, "executable_identity_invalid")
    return {
        "dev": details.st_dev,
        "ino": details.st_ino,
        "uid": details.st_uid,
        "mode": stat.S_IMODE(details.st_mode),
        "kind": "symlink",
        "target": "rustup",
        "path_matches_lstat": True,
        "owner_ancestor_acl_safe": True,
    }


def _regular_file_bytes(root_fd: int) -> int:
    total = 0
    stack = [os.dup(root_fd)]
    try:
        while stack:
            directory_fd = stack.pop()
            try:
                for name in os.listdir(directory_fd):
                    details = os.stat(
                        name,
                        dir_fd=directory_fd,
                        follow_symlinks=False,
                    )
                    if stat.S_ISDIR(details.st_mode):
                        stack.append(
                            os.open(
                                name,
                                os.O_RDONLY
                                | os.O_DIRECTORY
                                | os.O_CLOEXEC
                                | os.O_NOFOLLOW,
                                dir_fd=directory_fd,
                            )
                        )
                    elif stat.S_ISREG(details.st_mode):
                        total += details.st_size
                    elif not stat.S_ISLNK(details.st_mode):
                        raise RunnerError(
                            65,
                            "executable_identity_invalid",
                        )
            finally:
                os.close(directory_fd)
    finally:
        while stack:
            os.close(stack.pop())
    return total


