def _revalidate_rustup_resolution(
    validation: dict[str, object],
) -> None:
    authority = validation["_authority"]
    if not isinstance(authority, dict):
        raise RunnerError(65, "executable_identity_drift")
    executable_map = authority["executables"]
    regular_files = authority["regular_files"]
    symlinks = authority["symlinks"]
    directories = authority["directories"]
    directory_manifests = authority["directory_manifests"]
    if not all(
        isinstance(value, dict)
        for value in (
            executable_map,
            regular_files,
            symlinks,
            directories,
            directory_manifests,
        )
    ):
        raise RunnerError(65, "executable_identity_drift")
    records = validation["executables"]
    if not isinstance(records, list):
        raise RunnerError(65, "executable_identity_drift")
    for record in records:
        if not isinstance(record, dict):
            raise RunnerError(65, "executable_identity_drift")
        executable = executable_map[str(record["role"])]
        if not isinstance(executable, HeldExecutable):
            raise RunnerError(65, "executable_identity_drift")
        record["post"] = _executable_identity(executable)
        if record["post"] != record["pre"]:
            raise RunnerError(65, "executable_identity_drift")
    rustup_resolution = validation["rustup_resolution"]
    if not isinstance(rustup_resolution, dict):
        raise RunnerError(65, "executable_identity_drift")
    for name, path in (
        ("cargo_shim_post", "/home/spenser/.cargo/bin/cargo"),
        ("rustc_shim_post", "/home/spenser/.cargo/bin/rustc"),
    ):
        observed = _held_symlink(path)
        pre_name = name.replace("_post", "_pre")
        if observed != symlinks[path] or observed != rustup_resolution[pre_name]:
            raise RunnerError(65, "executable_identity_drift")
        rustup_resolution[name] = observed
    for name, path in (
        ("settings_post", "/home/spenser/.rustup/settings.toml"),
        (
            "repo_toolchain_file_post",
            os.path.join(REPOSITORY_CANONICAL_PATH, "rust-toolchain.toml"),
        ),
    ):
        descriptor, pre = regular_files[path]
        if type(descriptor) is not int or not isinstance(pre, dict):
            raise RunnerError(65, "executable_identity_drift")
        details = os.fstat(descriptor)
        named = os.stat(path, follow_symlinks=False)
        _acl_sha256, foreign_write = read_effective_acl(descriptor)
        observed = {
            "dev": details.st_dev,
            "ino": details.st_ino,
            "uid": details.st_uid,
            "mode": stat.S_IMODE(details.st_mode),
            "kind": "regular",
            "sha256": hash_open_file(descriptor),
            "path_matches_fd": (
                (details.st_dev, details.st_ino)
                == (named.st_dev, named.st_ino)
            ),
            "owner_ancestor_acl_safe": not foreign_write,
        }
        if observed != pre:
            raise RunnerError(65, "executable_identity_drift")
        rustup_resolution[name] = observed
    toolchain_root = validation["rust_toolchain_root"]
    if not isinstance(toolchain_root, dict):
        raise RunnerError(65, "executable_identity_drift")
    toolchain_path = str(authority["toolchain_path"])
    toolchain_descriptor, toolchain_pre = directories[toolchain_path]
    observed_directory = _directory_identity(
        toolchain_descriptor,
        toolchain_path,
    )
    manifest = _manifest_tree(toolchain_descriptor)
    if (
        observed_directory != toolchain_pre
        or manifest
        != (
            toolchain_root["manifest_pre_sha256"],
            toolchain_root["directory_count"],
            toolchain_root["file_count"],
            toolchain_root["symlink_count"],
        )
        or _regular_file_bytes(toolchain_descriptor)
        != toolchain_root["regular_file_bytes"]
    ):
        raise RunnerError(65, "executable_identity_drift")
    for path, (descriptor, identity) in directories.items():
        if (
            _directory_identity(descriptor, path) != identity
            or _manifest_tree(descriptor) != directory_manifests[path]
        ):
            raise RunnerError(65, "executable_identity_drift")
    toolchain_root["source_post"] = observed_directory.as_dict()
    toolchain_root["manifest_post_sha256"] = manifest[0]


def _close_rustup_resolution(validation: Mapping[str, object]) -> None:
    authority = validation.get("_authority")
    if not isinstance(authority, dict):
        return
    for mapping_name in ("executables", "regular_files", "directories"):
        mapping = authority.get(mapping_name)
        if not isinstance(mapping, dict):
            continue
        for value in mapping.values():
            descriptor = value.fd if isinstance(value, HeldExecutable) else value[0]
            try:
                os.close(int(descriptor))
            except OSError:
                pass


def run_authenticated_self_tests(
    repository: str,
    expected_head: str,
    git: HeldExecutable,
    *,
    gitdir_fd: int | None = None,
) -> tuple[int, bytes, bytes]:
    owns_gitdir = gitdir_fd is None
    active_gitdir = _open_validated_gitdir(repository) if owns_gitdir else gitdir_fd
    assert active_gitdir is not None
    try:
        runner_source, runner_oid = read_expected_head_blob(
            repository,
            expected_head,
            "scripts/ci/canonical_shell_wall_runner.py",
            git,
            gitdir_fd=active_gitdir,
        )
        test_source, test_oid = read_expected_head_blob(
            repository,
            expected_head,
            "scripts/ci/test_canonical_shell_wall_runner.py",
            git,
            gitdir_fd=active_gitdir,
        )
    finally:
        if owns_gitdir:
            os.close(active_gitdir)
    if inline_sha256(runner_source) != globals().get("__CANONICAL_RUNNER_SHA256"):
        raise RunnerError(65, "invocation_authority_invalid")
    runner_module = sys.modules.get(__name__)
    if (
        not isinstance(runner_module, types.ModuleType)
        or globals().get("__CANONICAL_MODULE_SOURCE") != runner_source
        or runner_module.__dict__ is not globals()
    ):
        raise RunnerError(65, "invocation_authority_invalid")
    previous = sys.modules.get("canonical_shell_wall_runner")
    sys.modules["canonical_shell_wall_runner"] = runner_module
    try:
        test_module = load_authenticated_module(
            "canonical_shell_wall_runner_selftest",
            test_source,
            f"<git-blob:{expected_head}:scripts/ci/test_canonical_shell_wall_runner.py>",
            inline_sha256(test_source),
            authenticated_self_test=True,
        )
        expected_ids = tuple(test_module.SELF_TEST_IDS)
        if len(expected_ids) != 99 or len(set(expected_ids)) != 99:
            raise RunnerError(65, "invocation_authority_invalid")
        suite_class = test_module.CanonicalShellWallRunnerTests
        discovered = {
            name
            for name in dir(suite_class)
            if name.startswith("test_") and callable(getattr(suite_class, name))
        }
        if discovered != set(expected_ids):
            raise RunnerError(65, "invocation_authority_invalid")
        suite = unittest.TestSuite(suite_class(name) for name in expected_ids)
        details = io.StringIO()
        result = unittest.TextTestRunner(
            stream=details,
            verbosity=0,
            failfast=False,
            buffer=True,
        ).run(suite)
        failed = len(result.failures) + len(result.errors)
        payload = {
            "failed": failed,
            "run": result.testsRun,
            "schema": SELF_TEST_SCHEMA,
            "status": "clean" if result.wasSuccessful() else "failed",
        }
        stdout = (
            json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n"
        ).encode("ascii")
        return (0 if result.wasSuccessful() else 68), stdout, b""
    finally:
        if previous is None:
            sys.modules.pop("canonical_shell_wall_runner", None)
        else:
            sys.modules["canonical_shell_wall_runner"] = previous


def _read_authenticated_staged_provenance(
    authority: Mapping[str, object],
    original: Mapping[str, object],
) -> dict[str, object]:
    provenance_artifact = authority.get("provenance_artifact")
    if provenance_artifact is not None:
        if not isinstance(provenance_artifact, dict):
            raise RunnerError(71, "evidence_write_failed")
        staged = _read_json_from_preopened_artifact(
            int(authority["partial_fd"]),
            provenance_artifact,
        )
    else:
        staged = _read_json_file_at(
            int(authority["partial_fd"]),
            "provenance.json",
        )
    immutable_top = (
        "schema",
        "invocation_id",
        "label",
        "mode",
        "started_at_utc",
    )
    if (
        any(staged.get(key) != original.get(key) for key in immutable_top)
        or staged.get("eligible") is not False
        or staged.get("wall_gate") != "ineligible"
        or staged.get("record_stage")
        not in {"preflight", "setup", "containment", "cleanup"}
        or not isinstance(staged.get("request"), dict)
        or not isinstance(original.get("request"), dict)
    ):
        raise RunnerError(71, "evidence_write_failed")
    staged_launcher = staged["request"].get("launcher")
    original_launcher = original["request"].get("launcher")
    if not isinstance(staged_launcher, dict) or not isinstance(
        original_launcher,
        dict,
    ):
        raise RunnerError(71, "evidence_write_failed")
    for key in (
        "authority_commit_oid",
        "runner_blob_sha256",
        "bootstrap_sha256",
        "host_argv_sha256",
    ):
        if staged_launcher.get(key) != original_launcher.get(key):
            raise RunnerError(71, "evidence_write_failed")
    staged_namespace = staged.get("namespace")
    original_namespace = original.get("namespace")
    if not isinstance(staged_namespace, dict) or not isinstance(
        original_namespace,
        dict,
    ):
        raise RunnerError(71, "evidence_write_failed")
    staged_host_fields = (
        staged_launcher.get("stage_a_argv_sha256"),
        staged_namespace.get("stage_a_bwrap_pid"),
        staged_namespace.get("stage_a_bwrap_start_time_ticks"),
        staged_namespace.get("stage_a_bwrap_pidfd_opened"),
    )
    original_host_fields = (
        original_launcher.get("stage_a_argv_sha256"),
        original_namespace.get("stage_a_bwrap_pid"),
        original_namespace.get("stage_a_bwrap_start_time_ticks"),
        original_namespace.get("stage_a_bwrap_pidfd_opened"),
    )
    default_host_fields = (None, None, None, False)
    if staged_host_fields != default_host_fields:
        raise RunnerError(71, "evidence_write_failed")
    if original_host_fields != default_host_fields:
        argv_sha256, bwrap_pid, start_time_ticks, pidfd_opened = (
            original_host_fields
        )
        if (
            not isinstance(argv_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", argv_sha256) is None
            or type(bwrap_pid) is not int
            or not 1 <= bwrap_pid <= MAX_PID
            or type(start_time_ticks) is not int
            or start_time_ticks <= 0
            or pidfd_opened is not True
        ):
            raise RunnerError(71, "evidence_write_failed")
        staged_launcher["stage_a_argv_sha256"] = argv_sha256
        staged_namespace.update(
            {
                "stage_a_bwrap_pid": bwrap_pid,
                "stage_a_bwrap_start_time_ticks": start_time_ticks,
                "stage_a_bwrap_pidfd_opened": True,
            }
        )
    return staged


def host_main(arguments: Mapping[str, object]) -> int:
    python_runtime = validate_python_runtime(require_bootstrap=True)
    if os.getcwd() != REPOSITORY_CANONICAL_PATH:
        raise RunnerError(65, "repository_identity_mismatch")
    try:
        signal.signal(signal.SIGCHLD, signal.SIG_DFL)
    except BaseException as error:
        raise RunnerError(68, "subreaper_unverified") from error
    if signal.getsignal(signal.SIGCHLD) is not signal.SIG_DFL:
        raise RunnerError(68, "subreaper_unverified")
    if not set_child_subreaper():
        raise RunnerError(68, "subreaper_unverified")
    namespace_scan_exemptions = (
        _capture_inaccessible_namespace_scan_exemptions()
    )
    _reject_product_home_selection(str(arguments["evidence_parent"]))
    expected_head = str(arguments["expected_head"])
    bootstrap_gitdir_fd = globals().get("__CANONICAL_BOOTSTRAP_GITDIR_FD")
    if type(bootstrap_gitdir_fd) is not int or bootstrap_gitdir_fd < 0:
        raise RunnerError(65, "invocation_authority_invalid")
    _validated_gitdir_identity(REPOSITORY_CANONICAL_PATH, bootstrap_gitdir_fd)
    held = validate_platform_startup_tcb()
    validate_host_account_projection()
    validate_subordinate_id_configuration()
    authority: dict[str, object] | None = None
    user_namespaces: PreparedAclUserNamespaces | None = None
    spawned: SpawnedProcess | None = None
    stage_a_reaped = False
    stage_a_pidfd_closed = False
    stage_a_process_teardown_proved = False
    stage_a_start_time: int | None = None
    stage_a_namespace_inodes: dict[str, int] | None = None
    stage_a_namespace_reference_baseline: frozenset[
        tuple[str, int]
    ] | None = None
    status_fd: int | None = None
    provenance: dict[str, object] | None = None
    toolchain_validation: dict[str, object] | None = None
    cargo_search_authority: list[dict[str, object]] = []
    repository_metadata_authorities: list[dict[str, object]] = []
    try:
        repository = verify_clean_repository(
            REPOSITORY_CANONICAL_PATH,
            expected_head,
            held["/usr/bin/git"],
            gitdir_fd=bootstrap_gitdir_fd,
            retained_metadata=repository_metadata_authorities,
        )
        if {
            str(authority["relative"])
            for authority in repository_metadata_authorities
        } != {
            "HEAD",
            f"refs/heads/{repository['branch']}",
            "config",
            "index",
            "info/exclude",
        }:
            raise RunnerError(72, "internal_invariant_failed")
        cargo_search_authority = retain_cargo_search_path_absence()
        _verify_commit_trailers(repository["commit"])
        runner_source, runner_oid = read_expected_head_blob(
            REPOSITORY_CANONICAL_PATH,
            expected_head,
            "scripts/ci/canonical_shell_wall_runner.py",
            held["/usr/bin/git"],
            gitdir_fd=bootstrap_gitdir_fd,
        )
        if inline_sha256(runner_source) != globals().get("__CANONICAL_RUNNER_SHA256"):
            raise RunnerError(65, "invocation_authority_invalid")
        toolchain_validation = validate_rustup_resolution()
        platform_roles = (
            ("bubblewrap", "/usr/bin/bwrap", "bubblewrap 0.11.0"),
            ("python", "/usr/bin/python3.13", "Python 3.13.7"),
            ("git", "/usr/bin/git", "git version 2.51.0"),
            ("newuidmap", "/usr/bin/newuidmap", "shadow 4.18.0-1"),
            ("newgidmap", "/usr/bin/newgidmap", "shadow 4.18.0-1"),
        )
        toolchain = {
            "platform": "linux",
            "machine": "x86_64",
            "executables": [
                {
                    "role": role,
                    "path": path,
                    "version": version,
                    "pre": _executable_identity(held[path]),
                    "post": None,
                }
                for role, path, version in platform_roles
            ]
            + list(toolchain_validation["executables"]),
            "python_runtime": python_runtime,
            "rustup_resolution": toolchain_validation[
                "rustup_resolution"
            ],
            "rust_toolchain_root": toolchain_validation[
                "rust_toolchain_root"
            ],
        }
        invocation_id = os.urandom(16).hex()
        mode = str(arguments["mode"])
        label = str(arguments["label"])
        timeout_seconds = int(arguments["timeout_seconds"])
        command = _canonical_cargo_command(mode)
        environment = dict(os.environ)
        provenance = _default_provenance(
            invocation_id=invocation_id,
            label=label,
            mode=mode,
            timeout_seconds=timeout_seconds,
            expected_head=expected_head,
            command=command,
            environment=environment,
        )
        provenance["toolchain"] = toolchain
        provenance["repository"] = {
            "branch": repository["branch"],
            "head": expected_head,
            "tree": repository["tree"],
            "cwd": REPOSITORY_CANONICAL_PATH,
            "clean": repository["clean"],
            "alternates_absent": True,
            "replace_refs_absent": True,
            "grafts_absent": True,
            "shallow_absent": True,
            "local_config_allowlist_valid": repository[
                "local_config_allowlist_valid"
            ],
            "worktree_config_absent": True,
            "info_attributes_absent": True,
            "tree_index_equal": True,
            "ignore_sources_tracked": True,
            "untracked_absent": True,
            "gitdir_identity": repository["gitdir_identity"],
            "index_pre": repository["index_identity"],
            "index_post": None,
            "head_file_pre": repository["head_file_identity"],
            "head_file_post": None,
            "branch_ref_pre": repository["branch_ref_identity"],
            "branch_ref_post": None,
            "local_config_pre": repository["local_config_identity"],
            "local_config_post": None,
            "info_exclude_pre": repository["info_exclude_identity"],
            "info_exclude_post": None,
            "tree_manifest_sha256": repository["tree_manifest_sha256"],
            "index_manifest_pre_sha256": repository[
                "index_manifest_sha256"
            ],
            "index_manifest_post_sha256": None,
            "ignore_sources_manifest_pre_sha256": repository[
                "ignore_sources_manifest_sha256"
            ],
            "ignore_sources_manifest_post_sha256": None,
            "tracked_manifest_pre_sha256": repository[
                "tracked_manifest_sha256"
            ],
            "tracked_manifest_post_sha256": None,
            "untracked_paths_pre_sha256": repository["untracked_paths_sha256"],
            "untracked_paths_post_sha256": None,
            "ignored_paths_pre_sha256": repository["ignored_paths_sha256"],
            "ignored_paths_post_sha256": None,
            "tracked_count": repository["tracked_count"],
        }
        provenance["request"]["launcher"]["runner_blob_sha256"] = inline_sha256(
            runner_source
        )
        provenance["request"]["launcher"][
            "authority_commit_trailers_verified"
        ] = True
        provenance["request"]["launcher"]["host_argv_sha256"] = str(
            arguments["_runtime_argv_sha256"]
        )
        authority = prepare_backing_root(
            str(arguments["evidence_parent"]),
            label,
            invocation_id,
        )
        _initialize_staged_artifact_authorities(authority)
        provenance["mounts"]["evidence_parent"] = {
            "pre": authority["parent_identity"].as_dict(),
            "post": None,
        }
        provenance["mounts"]["backing_mountpoint"].update(
            {
                "path": authority["backing_path"],
                "underlying_pre": authority["backing_identity"].as_dict(),
                "mounted": True,
            }
        )
        _rewrite_retained_json_artifact(
            int(authority["partial_fd"]),
            authority["provenance_artifact"],
            provenance,
        )
        stage_a_namespace_reference_baseline = _namespace_reference_census(
            inaccessible_exemptions=namespace_scan_exemptions,
        )
        user_namespaces = prepare_acl_user_namespaces(
            held["/usr/bin/newuidmap"],
            held["/usr/bin/newgidmap"],
        )
        spawned, status_fd, stage_a_argv = launch_stage_a_bwrap(
            bwrap=held["/usr/bin/bwrap"],
            user_namespaces=user_namespaces,
            source=runner_source,
            authority=authority,
            repository=REPOSITORY_CANONICAL_PATH,
            rustup_source=RUSTUP_SOURCE_PATH,
            cargo_source=CARGO_SOURCE_PATH,
            mode=mode,
            label=label,
            timeout_seconds=timeout_seconds,
            expected_head=expected_head,
            environment=environment,
        )
        close_prepared_acl_user_namespaces(user_namespaces)
        user_namespaces = None
        start_time = _process_start_time_ticks(spawned.pid)
        stage_a_start_time = start_time
        provenance["request"]["launcher"]["stage_a_argv_sha256"] = inline_sha256(
            _nul_frame(stage_a_argv)
        )
        provenance["namespace"].update(
            {
                "stage_a_bwrap_pid": spawned.pid,
                "stage_a_bwrap_start_time_ticks": start_time,
                "stage_a_bwrap_pidfd_opened": True,
            }
        )
        status_deadline = (
            time.monotonic()
            + SNAPSHOT_TIMEOUT_SECONDS
            + SETUP_TIMEOUT_SECONDS
            + timeout_seconds
            + CLEANUP_TIMEOUT_SECONDS
        )
        first_status_line = _read_one_line(
            status_fd,
            deadline=status_deadline,
        )
        first = _parse_first_bwrap_record(first_status_line)
        stage_a_namespace_inodes = {
            "mnt": int(first["mnt-namespace"]),
            "pid": int(first["pid-namespace"]),
        }
        status_rest = _read_fd_bounded(
            status_fd,
            MAX_STATUS_BYTES - len(first_status_line),
            status_deadline,
        )
        os.close(status_fd)
        status_fd = None
        _first, final = parse_bwrap_status(first_status_line + status_rest)
        stage_a_status = _reap_exact_spawned_before_deadline(
            spawned,
            deadline=status_deadline,
        )
        stage_a_reaped = True
        if stage_a_status != 0:
            raise RunnerError(68, "stage_a_liveness_failed")
        _reap_owned_children_to_echild(
            time.monotonic() + CLEANUP_TIMEOUT_SECONDS
        )
        stage_a_process_teardown_proved = True
        if final["exit-code"] != 0:
            raise RunnerError(68, "stage_a_liveness_failed")
        if not verify_namespace_mount_teardown(
            spawned.pid,
            spawned.pidfd,
            expected_start_time=start_time,
            expected_namespace_inodes=stage_a_namespace_inodes,
            inaccessible_exemptions=namespace_scan_exemptions,
        ):
            raise RunnerError(70, "mount_teardown_failed")
        if stage_a_namespace_reference_baseline is None:
            raise RunnerError(72, "internal_invariant_failed")
        _verify_spawned_namespace_boundary_teardown(
            spawned,
            stage_a_namespace_reference_baseline,
            inaccessible_exemptions=namespace_scan_exemptions,
        )
        os.close(spawned.pidfd)
        stage_a_pidfd_closed = True
        staged = _read_authenticated_staged_provenance(
            authority,
            provenance,
        )
        staged["namespace"]["stage_a_namespace_absent"] = True
        _discard_unused_staged_artifacts(authority, staged)
        nested_namespace_inodes = _captured_stage_b_namespace_inodes(staged)
        if (
            staged.get("record_stage") != "cleanup"
            or staged.get("containment", {}).get("echld_observed") is not True
            or staged.get("containment", {}).get("authenticated_empty_record")
            is not True
            or staged.get("containment", {}).get("output_eof_after_stage_b_reap")
            is not True
            or nested_namespace_inodes is None
            or staged.get("mounts", {}).get("stage_b", {}).get("unmounted")
            is not True
        ):
            raise RunnerError(70, "cleanup_failed")
        verify_namespace_inodes_absent(
            nested_namespace_inodes,
            inaccessible_exemptions=namespace_scan_exemptions,
        )
        repository_post = verify_clean_repository(
            REPOSITORY_CANONICAL_PATH,
            expected_head,
            held["/usr/bin/git"],
            gitdir_fd=bootstrap_gitdir_fd,
        )
        _revalidate_retained_git_metadata(
            bootstrap_gitdir_fd,
            repository_metadata_authorities,
        )
        validate_subordinate_id_configuration()
        revalidate_cargo_search_path_absence(cargo_search_authority)
        stable_repository_keys = (
            "head",
            "tree",
            "branch",
            "tree_manifest_sha256",
            "index_manifest_sha256",
            "ignore_sources_manifest_sha256",
            "tracked_manifest_sha256",
            "untracked_paths_sha256",
            "ignored_paths_sha256",
            "tracked_count",
        )
        if any(
            repository_post[key] != repository[key]
            for key in stable_repository_keys
        ):
            raise RunnerError(65, "repository_identity_mismatch")
        _revalidate_rustup_resolution(toolchain_validation)
        python_runtime_post = validate_python_runtime(
            require_bootstrap=True,
            include_post=True,
        )
        if python_runtime_post != python_runtime:
            python_runtime = python_runtime_post
        for record, (_role, path, _version) in zip(
            toolchain["executables"][: len(platform_roles)],
            platform_roles,
            strict=True,
        ):
            record["post"] = _executable_identity(held[path])
            if record["post"] != record["pre"]:
                raise RunnerError(65, "executable_identity_drift")
        toolchain["python_runtime"] = python_runtime
        staged["repository"].update(
            {
                "index_post": repository_post["index_identity"],
                "head_file_post": repository_post["head_file_identity"],
                "branch_ref_post": repository_post["branch_ref_identity"],
                "local_config_post": repository_post["local_config_identity"],
                "info_exclude_post": repository_post["info_exclude_identity"],
                "index_manifest_post_sha256": repository_post[
                    "index_manifest_sha256"
                ],
                "ignore_sources_manifest_post_sha256": repository_post[
                    "ignore_sources_manifest_sha256"
                ],
                "tracked_manifest_post_sha256": repository_post[
                    "tracked_manifest_sha256"
                ],
                "untracked_paths_post_sha256": repository_post[
                    "untracked_paths_sha256"
                ],
                "ignored_paths_post_sha256": repository_post[
                    "ignored_paths_sha256"
                ],
            }
        )
        staged["toolchain"] = toolchain
        staged["namespace"].update(
            {
                "stage_a_status_received": True,
                "stage_a_exit_received": True,
                "stage_a_namespace_absent": True,
            }
        )
        staged["mounts"]["stage_a"].update(
            {
                "completed": True,
                "unmounted": True,
            }
        )
        staged["mounts"]["tmpfs"]["unmounted"] = True
        staged["mounts"]["proc"]["unmounted"] = True
        staged["containment"].update(
            {
                "stage_a_exit": 0,
                "stage_a_namespace_absent": True,
            }
        )
        staged["finalized_at_utc"] = time.strftime(
            "%Y-%m-%dT%H:%M:%SZ",
            time.gmtime(),
        )
        final_directory = finalize_after_stage_a_exit(authority, staged)
        os.close(int(authority["parent_fd"]))
        authority = None
        gate = staged["wall_gate"]
        print(f"wall_gate={gate} invocation_id={invocation_id}")
        return 0 if gate == "clean" else 69
    except RunnerError as error:
        namespace_teardown_proved = spawned is None
        nested_namespace_teardown_proved = spawned is None
        namespace_boundary_teardown_proved = spawned is None
        if spawned is not None and not stage_a_reaped:
            _terminate_exact_spawned_process(spawned)
            stage_a_reaped = True
        if spawned is not None and not stage_a_process_teardown_proved:
            try:
                _reap_owned_children_to_echild(
                    time.monotonic() + CLEANUP_TIMEOUT_SECONDS
                )
            except RunnerError:
                stage_a_process_teardown_proved = False
            else:
                stage_a_process_teardown_proved = True
        if (
            spawned is not None
            and not stage_a_pidfd_closed
            and stage_a_namespace_reference_baseline is not None
        ):
            try:
                _verify_spawned_namespace_boundary_teardown(
                    spawned,
                    stage_a_namespace_reference_baseline,
                    inaccessible_exemptions=namespace_scan_exemptions,
                )
            except RunnerError:
                namespace_boundary_teardown_proved = False
            else:
                namespace_boundary_teardown_proved = True
        if (
            spawned is not None
            and not stage_a_pidfd_closed
            and stage_a_namespace_inodes is not None
        ):
            try:
                verify_namespace_mount_teardown(
                    spawned.pid,
                    spawned.pidfd,
                    expected_start_time=stage_a_start_time,
                    expected_namespace_inodes=stage_a_namespace_inodes,
                    inaccessible_exemptions=namespace_scan_exemptions,
                )
            except RunnerError:
                namespace_teardown_proved = False
            else:
                namespace_teardown_proved = (
                    namespace_boundary_teardown_proved
                )
        elif spawned is not None and not stage_a_pidfd_closed:
            namespace_teardown_proved = namespace_boundary_teardown_proved
        if spawned is not None and not stage_a_pidfd_closed:
            os.close(spawned.pidfd)
            stage_a_pidfd_closed = True
        if status_fd is not None:
            try:
                os.close(status_fd)
            except OSError:
                pass
            status_fd = None
        if authority is not None and provenance is not None:
            _record_ineligibility(
                provenance,
                error.reason,
                error.exit_code,
            )
            staged_authenticated = False
            try:
                provenance = _read_authenticated_staged_provenance(
                    authority,
                    provenance,
                )
            except RunnerError:
                nested_namespace_teardown_proved = False
            else:
                staged_authenticated = True
                if stage_a_process_teardown_proved and namespace_teardown_proved:
                    provenance["namespace"]["stage_a_namespace_absent"] = True
                _record_ineligibility(
                    provenance,
                    error.reason,
                    error.exit_code,
                )
                _discard_unused_staged_artifacts(authority, provenance)
                nested_namespace_teardown_proved = (
                    stage_a_process_teardown_proved
                )
                try:
                    nested_namespace_inodes = (
                        _captured_stage_b_namespace_inodes(provenance)
                    )
                    if nested_namespace_inodes is not None:
                        verify_namespace_inodes_absent(
                            nested_namespace_inodes,
                            inaccessible_exemptions=(
                                namespace_scan_exemptions
                            ),
                        )
                    elif provenance.get("namespace", {}).get(
                        "stage_b_bwrap_pid"
                    ) is not None:
                        if not (
                            stage_a_process_teardown_proved
                            and namespace_teardown_proved
                        ):
                            raise RunnerError(70, "mount_teardown_failed")
                except RunnerError:
                    nested_namespace_teardown_proved = False
            if not (
                namespace_teardown_proved
                and nested_namespace_teardown_proved
                and staged_authenticated
            ):
                provenance["record_stage"] = "cleanup"
                selected_exit = _record_ineligibility(
                    provenance,
                    "mount_teardown_failed",
                    70,
                )
                stage_b_mount = provenance.get("mounts", {}).get("stage_b")
                if isinstance(stage_b_mount, dict):
                    stage_b_mount["unmounted"] = False
                _finalize_ineligible(
                    authority,
                    provenance,
                    RunnerError(70, "mount_teardown_failed"),
                    retain_backing=True,
                    stage_a_process_teardown_proved=(
                        stage_a_process_teardown_proved
                    ),
                )
                authority = None
                print(
                    "wall_gate=ineligible "
                    f"invocation_id={provenance['invocation_id']}"
                )
                return selected_exit
            _finalize_ineligible(authority, provenance, error)
            authority = None
            print(
                "wall_gate=ineligible "
                f"invocation_id={provenance['invocation_id']}"
            )
            return int(provenance["runner_exit_code"])
        raise
    finally:
        if user_namespaces is not None:
            close_prepared_acl_user_namespaces(user_namespaces)
        if spawned is not None and not stage_a_reaped:
            _terminate_exact_spawned_process(spawned)
        if spawned is not None and not stage_a_pidfd_closed:
            try:
                os.close(spawned.pidfd)
            except OSError:
                pass
        for executable in held.values():
            try:
                os.close(executable.fd)
            except OSError:
                pass
        if toolchain_validation is not None:
            _close_rustup_resolution(toolchain_validation)
        _close_retained_git_metadata(repository_metadata_authorities)
        close_cargo_search_path_authority(cargo_search_authority)
        if authority is not None:
            artifact_authorities = authority.get("artifact_authorities", {})
            if isinstance(artifact_authorities, dict):
                artifacts_to_close = artifact_authorities.values()
            else:
                artifacts_to_close = ()
            for artifact in artifacts_to_close:
                if isinstance(artifact, dict):
                    artifact_fd = int(artifact.get("fd", -1))
                    if artifact_fd < 0:
                        continue
                    try:
                        os.close(artifact_fd)
                    except OSError:
                        pass
            for key in ("backing_fd", "partial_fd", "parent_fd"):
                try:
                    os.close(int(authority[key]))
                except OSError:
                    pass
            for descriptor, _path, _identity in authority.get(
                "ancestor_records",
                (),
            ):
                try:
                    os.close(int(descriptor))
                except OSError:
                    pass


def _run_selftest_bootstrap(
    arguments: Sequence[str],
) -> tuple[int, bytes, bytes]:
    try:
        parse_args(arguments)
    except RunnerError as error:
        return error.exit_code, b"", f"{error.reason}\n".encode("ascii")
    return 0, b"", b""


