def main(argv: Sequence[str] | None = None) -> int:
    arguments = list(sys.argv[1:] if argv is None else argv)
    try:
        parsed = parse_args(arguments)
        parsed["_runtime_argv_sha256"] = _verify_runtime_argv(parsed)
        role = str(parsed["role"])
        if role == "host":
            return host_main(parsed)
        if role == "self-test":
            validate_python_runtime(require_bootstrap=True)
            if os.getcwd() != REPOSITORY_CANONICAL_PATH:
                raise RunnerError(65, "repository_identity_mismatch")
            bootstrap_gitdir_fd = globals().get("__CANONICAL_BOOTSTRAP_GITDIR_FD")
            if type(bootstrap_gitdir_fd) is not int or bootstrap_gitdir_fd < 0:
                raise RunnerError(65, "invocation_authority_invalid")
            _validated_gitdir_identity(
                REPOSITORY_CANONICAL_PATH,
                bootstrap_gitdir_fd,
            )
            held = validate_platform_startup_tcb()
            try:
                chain = verify_expected_head_object_chain(
                    REPOSITORY_CANONICAL_PATH,
                    str(parsed["expected_head"]),
                    held["/usr/bin/git"],
                    gitdir_fd=bootstrap_gitdir_fd,
                )
                _verify_commit_trailers(chain["commit"])
                code, stdout, stderr = run_authenticated_self_tests(
                    REPOSITORY_CANONICAL_PATH,
                    str(parsed["expected_head"]),
                    held["/usr/bin/git"],
                    gitdir_fd=bootstrap_gitdir_fd,
                )
                os.write(1, stdout)
                if stderr:
                    os.write(2, stderr)
                return code
            finally:
                for executable in held.values():
                    os.close(executable.fd)
        if role == "stage-a":
            validate_python_runtime(require_bootstrap=False)
            return stage_a_main(parsed)
        if role == "stage-b-worker":
            validate_python_runtime(require_bootstrap=False)
            return stage_b_worker_main(parsed)
        raise RunnerError(64, "invocation_authority_invalid")
    except RunnerError as error:
        os.write(2, f"{error.reason}\n".encode("ascii"))
        return error.exit_code
    except BaseException:
        os.write(2, b"internal_invariant_failed\n")
        return 72


if __name__ == "__main__":
    raise SystemExit(main())
